// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":117,"question":"رجل متزوج، وزوجته لا تُعِفُّه؛ فكلما رأى أخرى فكأنه غير متزوجٍ، لأسبابٍ يعلمها الله، وزوجته قالت: إذا تزوجتَ طلقني، فهل يُعدّد دون علمها ثم يُخبرها، مع أنها عصبية جدًّا، أم إذا وقفت عائقًا طلَّقها؟ وهل زواجه من الثانية يُعتبر واجبًا؛ لأنَّ زوجته الأولى لا تعفّه؟","title":"ماذا يفعل من كانت زوجته لا تُعِفُّه؟","answer":"الجواب: إذا كانت لا تعفّه فيلزمه النكاح إذا كان يقدر، فيتزوج ثانيةً، وإذا ما عفَّته الثانية يتزوج ثالثة، وإذا ما عفته الثالثة يتزوج رابعةً؛ حتى يعفَّ نفسه إذا كان يقدر وعنده مال، ولو ما رضيت الزوجة، لكن يُرضي الجميع بالكلام الطيب والأسلوب الحسن، والعدل، فعليه أن يتحرى العدل، ويسأل ربَّه أن يهديهنَّ، وأن يَمُنَّ عليهنَّ بالموافقة، ويجتهد، والحمد لله، مثلما قال جلَّ وعلا: فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلَاثَ وَرُبَاعَ فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا فَوَاحِدَةً [النساء:3].","link":"https://binbaz.org.sa/fatwas/3555/ماذا-يفعل-من-كانت-زوجته-لا-تعفه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0102.mp3","categories":["تعدد الزوجات"]},{"id":302,"question":"رجلٌ لديه زوجتان، وأحد الزوجتين أحسن معاملةً لزوجها من الأخرى في المأكل والملبس والفراش، هل يجوز له أن يُفضِّلها على الأخرى؟","title":"حكم تفضيل إحدى الزوجتين لتقصير الأخرى","answer":"الجواب:\n\nالواجب عليه العدل بين الزوجتين، فالله سبحانه أوصى بالعدل، فعليه أن يعدل بينهما، وعليه أن يُعلِّم التي قد ساءت أخلاقُها أو قصَّرت في حقِّه، عليه أن يُعلِّمها ويُوجهها إلى الخير بالحكمة والكلام الطيب.\nوقد صحَّ عن رسول الله عليه الصلاة والسلام أنه قال: مَن كانت له امرأتان فمال إلى إحداهما جاء يوم القيامة وشِقّه مائل.\nفالواجب العدل بين الزوجات، قالت عائشة رضي الله عنها: كان النبيُّ ﷺ يقسم بين نسائه فيعدل، ويقول: اللهم هذا قسمي فيما أملك، فلا تلمني فيما تملك ولا أملك.\n\nالشيء الذي يقدر عليه من القسمة بينهنَّ في الوقت وفي جميع أحواله وفي النَّفقة يفعل ذلك، أما ما لا يملك من جهة الحبِّ وما يتبعه من الوطء فهذا لا يلزمه فيها التعديل؛ فإنَّ الحبَّ بيد الله، ليس بيده هو، قد تكون هذه أحبَّ من هذه، وقد يشتهي هذه أكثر من هذه، وليس باختياره، هذا لا يلزم فيه العدل، ولا يأثم إذا جامع هذه أكثر من هذه، أو أحبَّ هذه أكثر من هذه؛ لأنَّ هذه أمور بيد الله، ليس في يد العبد.\nأما كونه يعدل فيها بإعطاء حقِّها من يومها وليلتها ونفقتها؛ فهذا واجبٌ، يقول النبيُّ ﷺ: ولهن عليكم رزقهنَّ وكسوتهنَّ بالمعروف، ما قال: والعدل بينهنَّ في الوطء، أو في الحب، لا، هذا ما يملكه الإنسانُ، ليس باختياره، لكن إذا كانت إحداهنَّ تُسيئ العشرة ولا تقوم بالواجب؛ يُعْلِمها ويُوجهها ويعمل معها ما يلزم من الإصلاح: من الوعظ والتَّذكير، أو الهجر، أو التأديب إذا دعت الحاجةُ إلى ذلك ولم ينفع الهجر ولم ينفع الوعظ.","link":"https://binbaz.org.sa/fatwas/4304/حكم-تفضيل-احدى-الزوجتين-لتقصير-الاخرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0351.mp3","categories":["الشروط والعيوب في النكاح","تعدد الزوجات"]},{"id":313,"question":"(تعدد الزوجات) يتنكَّر لها الناسُ، وبعضهم يتصور أنَّها مُحرَّمة، والآن المجتمع يوجد به عنوسة خطيرة؟","title":"ما المنافع التي تحصل بتعدُّد الزوجات؟","answer":"الجواب: الله يقول جلَّ وعلا: فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلَاثَ وَرُبَاعَ فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا فَوَاحِدَةً أَوْ مَا مَلَكَتْ أَيْمَانُكُمْ [النساء:3]، فالأصل التَّعدد، وذلك في مصلحة الرجال والنِّساء، فالتعدد ينفع الرجل والمرأة، فالرجل قد لا تكفيه الواحدة، قد يكون عنده قوة الشَّهوة، فالواحدة لا تكفي، فيحتاج إلى ثنتين أو ثلاث أو أربع حتى يعفّ نفسه، وحتى يغضَّ بصره، وحتى يحصّن فرجه.\nوهكذا النساء في الحاجة إلى الرجال، فإذا لم يتزوج إلا واحدةً بقي كثيرٌ من النساء ما لهن أزواج، فإذا تعدد النّساء حصل للنِّساء مصلحة من ذلك، فكونها تكون عند زوجٍ ولو عنده غيرها خيرٌ لها من بقائها ليس عندها زوجٌ.\nفالمقصود أنَّ التَّعدد هو السُّنة، وهو الأصلح، وهو الأنفع للجميع، إذا كان الزوج يستطيع ذلك، فإن كونها تُعطى نصف رجلٍ أو ثلث رجلٍ أو ربع رجلٍ خيرٌ لها من بقائها عانسةً ليس عندها أحدٌ.\nفينبغي للنساء أن يعرفن هذا الأمر، وأن يحذرن الغيرة الضَّارة، وهكذا أولياؤهن، فلا ينبغي أن تمتنع المرأةُ من الزواج ممن عنده امرأة أو عنده امرأتان أو عنده ثلاث، لا، الله أباح له هذا، وفيه مصالح كثيرة للرجال والنساء، فيه إحصانٌ للفروج، فيه عفَّة للرجل والمرأة، فيه غضّ الأبصار، فيه مساعدة الفقيرة والقيام عليها، وفيه حمايتها وصيانتها عن الفساد.\nففي النكاح المُتعدد خيرٌ كثيرٌ، ومصالح كبيرة، ولكن كثيرًا من النساء يجهل ذلك، وبعض الأولياء يجهل ذلك، فالواجب التَّنَبُّه لهذا الأمر، فنصف الرجل وربع الرجل وثلث الرجل خيرٌ من بقائها وحدها، ثم الرجل يدخل عليها، ويصونها، ويُهاب، ويُنْفِق عليها إذا كانت فقيرةً.\nوعلى كل حالٍ، المصلحة عظيمة في التَّعدد، وهكذا كل ما شرع الله فيه مصلحة عظيمة، وإن جهل الناس ذلك، والله ما شرع التَّعدد إلا لمصلحةٍ.\nوكان فيمَن قبلنا يُباح للرجل أن يجمع تسعين ومئة، كان عند سليمان بن داود تسعون امرأةً عليه الصلاة والسلام، تسعون، وكان عند أبيه داود مئة امرأةٍ، ثم منع الله في شريعة محمدٍ ما زاد عن أربعٍ، خفف على هذه الأمة، وجعلها أربعًا فقط، ولكن النِّساء ما يعقلن هذا الأمر، وبعض الأولياء كذلك ما يعقلن المصلحة، ولهذا فكثيرٌ منهن يكره التَّعدد، ويأبى من التَّعدد، ويمتنع من التزوج بمَن عنده امرأة.\nوبعض دُعاة الباطل في بعض الإذاعات والصَّحافة أو غير ذلك يفعلون ما يُنَفِّر المرأةَ من الزوج الذي عنده امرأة، كأنَّها جريمة، هذا منكرٌ -نعوذ بالله منه- وهؤلاء الذين يُنَفِّرون من ذلك جهلة بأمر الله، أو فُسَّاق عُصاة لله -نسأل الله العافية.\nفيجب التَّنَبُّه لهذا الأمر، والواجب على المؤمن أن يرضى بما شرع الله، يقول الله سبحانه: ذَلِكَ بِأَنَّهُمْ كَرِهُوا مَا أَنْزَلَ اللَّهُ فَأَحْبَطَ أَعْمَالَهُمْ [محمد:9]، الواجب على المؤمن والمؤمنة الرضا بما شرع الله، ومحبته، وعدم كراهته ولو على نفسه.","link":"https://binbaz.org.sa/fatwas/4318/ما-المنافع-التي-تحصل-بتعدد-الزوجات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0363.mp3","categories":["الشروط والعيوب في النكاح","تعدد الزوجات"]},{"id":448,"question":"الزوجة إذا اشترط على زوجها لو تزوج عليها فهي طالق، هل هو وجيه أو هو شرط مخالف للشرع؟","title":"حكم اشتراط الزوجة عدم الزواج عليها","answer":"الجواب: لها الخيار إذا اشترطت، المسلمون على شروطهم، الشرط ينفعها والزواج يضرها، وصرح العلماء أن لها شرطها  وأن لها الخيار؛ إن شاءت سمحت وإن شاءت فارقته، لا يحتاج طلاق ولا يحتاج شيء.\n(دروس شرح بلوغ المرام، كتاب البيوع)","link":"https://binbaz.org.sa/fatwas/6171/حكم-اشتراط-الزوجة-عدم-الزواج-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/shart006.mp3","categories":["الشروط والعيوب في النكاح","تعدد الزوجات"]},{"id":449,"question":"الأصل في التعدُّد أو الواحدة؟","title":"ما الأصل في الزواج؟ التعدد أم الواحدة","answer":"الجواب: الأصل التعدد فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ [النساء:3] هذا هو الأفضل؛ لما فيه من رحمة النساء وكثرة النسل وعفة النساء وعفة الرجل أيضاً، كلما كان العدد أكثر صار أعف للجميع للرجال وللنساء.\n(دروس شرح بلوغ المرام، كتاب البيوع)","link":"https://binbaz.org.sa/fatwas/6172/ما-الاصل-في-الزواج-التعدد-ام-الواحدة","audio":"https://files.zadapps.info/binbaz.org.sa/ta3dd007.mp3","categories":["تعدد الزوجات"]},{"id":507,"question":"من كان في الجامعة ومعه زوجة واحدة ويريد التزوج بأخرى سواء بكر أو ثيب، هل ترى أن يتزوج أم يصبر؟","title":"ما الضابط لمن أراد الزواج بأكثر من واحدة؟","answer":"الجواب: السُّنة الزواج، إذا تيسر له الزواج، يتزوج إذا تيسر له الزواج وعنده قدرة يتزوج، الله يقول: فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلَاثَ وَرُبَاعَ [النساء:3] إذا كان عنده قدرة ويعلم أنه يستطيع القيام عليهن، أما إذا كان يخاف فواحدة فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا فَوَاحِدَةً [النساء:3].\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6336/ما-الضابط-لمن-اراد-الزواج-باكثر-من-واحدة","audio":"https://files.zadapps.info/binbaz.org.sa/maram071 - 01 -  Start.mp3","categories":["تعدد الزوجات"]},{"id":559,"question":"المرأة إذا بعد ما تم الزواج فقالت لزوجها: لا تتزوج علي امرأة أخرى؟","title":"طلب الزوجة عدم الزواج عليها","answer":"الجواب: لا يجب عليه طاعتها.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6390/طلب-الزوجة-عدم-الزواج-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/maram125.mp3","categories":["تعدد الزوجات"]},{"id":569,"question":"بعضهم يشوِّه سمعة التعدد في النكاح؟","title":"ما حكم تشويه التعدد في الزوجات؟","answer":"الجواب: ما يصح، الله قال: فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلَاثَ وَرُبَاعَ [النساء:3] أمر به ثم قال:فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا فَوَاحِدَةً [النساء:3].\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6400/ما-حكم-تشويه-التعدد-في-الزوجات","audio":"https://files.zadapps.info/binbaz.org.sa/MARAM135 - 02 - .mp3","categories":["تعدد الزوجات"]},{"id":572,"question":"مسألة الذهاب للسفر بدون قرعة كأن يقول السنة أنت هذه واللي بعدها؟","title":"هل يجب الإقراع بين الزوجات في السفر؟","answer":"الجواب: ما يصلح إلا برضاها، ولو خرجت القرعة لواحدة مرتين ثلاث؛ ما في شيء؛ القرعة ما فيها حيف على أحد.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6403/هل-يجب-الاقراع-بين-الزوجات-في-السفر","audio":"https://files.zadapps.info/binbaz.org.sa/maram138 - 01 -  Start.mp3","categories":["تعدد الزوجات"]},{"id":574,"question":"رجل ساكن في الرياض وتزوج امرأة من جدة وهو يسافر إلى جدة أيامًا معدودة؟","title":"كيف يكون العدل بين الزوجات في عدة مُدُن؟","answer":"الجواب: يعدل، يجلس عندها خمسة أيام ويروح عند الأخرى خمسة أيام، ما في بأس.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6405/كيف-يكون-العدل-بين-الزوجات-في-عدة-مدن","audio":"https://files.zadapps.info/binbaz.org.sa/maram140 - 01 -  Start.mp3","categories":["تعدد الزوجات"]},{"id":732,"question":"يا شيخ، بلغني أنَّ بعض النساء تُفضّل أن يُعاشر زوجُها نساء بالحرام على أن يُعدد؟","title":"حكم مَن تفضل الحرام لزوجها على التعدُّد","answer":"الجواب: هذا كله من الجهل، هذا من الجهل العظيم، كونه يتَّخذ صاحبات وصديقات وخليلات بالحرام؛ هذا فسادٌ عظيمٌ عليها وعليه -والعياذ بالله- وقد يُعطلها بالكلية، ويستغني بالزانيات عنها -نسأل الله السلامة- وهذا من جهلها وضلالها وضعف إيمانها -نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/20610/حكم-من-تفضل-الحرام-لزوجها-على-التعدد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0547حكم من تفضل أن يعاشر زوجها الحرام على أن يعدد للشيخ عبدالعزيز بن باز رحمه الله.mp3","categories":["تعدد الزوجات"]},{"id":1026,"question":"هناك حربٌ شديدةٌ على تعدد الزوجات –يقصد من أعداء الإسلام- فنرجو إفراد هذا الموضوع بمحاضرةٍ، والتَّنبيه على أهميته، خاصَّةً بعد كثرة النساء والفتن؟","title":"حكم تعدد الزوجات في الإسلام","answer":"الجواب: تعدد النساء مشروعٌ، والله جلَّ وعلا بيَّن ذلك في كتابه العظيم، قال تعالى: وَإِنْ خِفْتُمْ أَلَّا تُقْسِطُوا فِي الْيَتَامَى فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلَاثَ وَرُبَاعَ [النساء:3]، وقد كان النبيُّ ﷺ عنده تسع نسوةٍ، توفي عنهن عليه الصلاة والسلام، كان في شريعة مَن قبلنا أكثر من ذلك: في شريعة التوراة كان عند سليمان تسعون امرأة، وجاء في بعض الأحاديث مئة امرأة، فشريعة التوراة كان فيها توسُّعٌ في هذا، ثم قصر الله أمة محمدٍ ﷺ على أربعٍ، ليس للإنسان أن يجمع أكثر من أربعٍ: مثنى، وثلاث، ورباع.\nوالتَّعدد سنة، إذا استطاع المؤمنُ ذلك وتيسر له ذلك؛ شُرع له أن يتزوج ثنتين أو ثلاثًا أو أربعًا على حسب طاقته؛ لما فيه من المصالح العظيمة: من تعدد الذرية، وكثرة الذرية، وتكثير الأمة التي قال فيها النبيُّ ﷺ: تزوَّجوا الودودَ الولودَ، فإني مُكاثِرٌ بكم الأممَ يوم القيامة، وفي هذا من المصالح: تكثير مَن يعبد الله ويُطيعه. وذلك أيضًا من أسباب العفَّة: غضُّ البصر، وعفَّة الفرج؛ لأنَّ بعض الرجال لا تعفّه الواحدةُ، يحتاج إلى زيادةٍ، والواحدة قد تُصاب بالمرض فلا يتمكَّن زوجُها من قضاء وطره، وتُصيبها العادة الشهرية، وتلد وتمكث مدةً طويلةً في النفاس لا يجوز له جماعها، فهو في حاجةٍ إلى المزيد والتَّعدد.\nولهذا شرع الله جلَّ وعلا التَّعدد رحمةً لعباده؛ لأنهم يحتاجون إلى ذلك، ثم النساء يحتجن إلى ذلك، فإنَّ كثرة النساء يحتاج إلى علاجٍ، وذلك بالتَّعدد، فإنَّ وجودها عند زوجٍ ولو عنده غيرها خيرٌ لها من بقائها بدون زوجٍ، ولو كانت ثانيةً أو ثالثةً أو رابعةً، هذا خيرٌ لها وأصلح؛ لعفَّة فرجها، وغضِّ بصرها، والإنفاق عليها، ولما يحصل من وراء ذلك من الذرية إذا قسم الله ذلك.\nفالتعدد فيه مصالح كثيرة للرجال والنساء وللأمة، فلا يكرهه إلا إنسانٌ جاهلٌ، أو امرأةٌ جاهلةٌ؛ لأن فيه مصالح كثيرةً، مع القدرة، أما مع العجز والخوف من عدم القدرة فمثلما قال سبحانه: فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا فَوَاحِدَةً [النساء:3]، أما إذا يسَّر الله عليه وعنده القُدرة فإنه يُشرع له التَّعدد إذا استطاع ذلك.","link":"https://binbaz.org.sa/fatwas/21071/حكم-تعدد-الزوجات-في-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0867حكم تعدد الزوجات في الإسلام؟ ابن باز فتاوى المحاضرات.mp3","categories":["تعدد الزوجات"]},{"id":2128,"question":"إنسان ابتُلي بشدة الشهوة، ولا يريد أن يُعلم زوجته؟","title":"هل يلزم إعلام الزوجة عند الزواج بأخرى؟","answer":"الجواب:\nيتزوج ويُعلن في المحل الذي فيه الزواج، فإذا صار في محلٍّ آخر يُعلنه، ما يصير كالزنا، يكون هناك إعلام عند الجيران...\nس: المقصود شدة الشهوة؟\nج: له أن يتزوج لكن لا يُخفيه، يُعْلِنه؛ حتى لا يكون شبيه الزنا.\nس: هل يُعلم زوجته؟\nج: إن أعلمها لا بأس، وإن لم يُعلمها لا بأس.","link":"https://binbaz.org.sa/fatwas/22246/هل-يلزم-اعلام-الزوجة-عند-الزواج-باخرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أراد أن يتزوج بأخرى فهل يعلم زوجته.mp3","categories":["تعدد الزوجات"]},{"id":3687,"question":"قول ابن حجر: فيه أن من غاب عن أزواجه ثم حضر يبدأ بمن شاء منهن ولا يلزمه أن يبدأ من حيث بلغ...؟","title":"بمن يبدأ من غاب عن زوجاته ثم حضر؟","answer":"الجواب: هذه البُدأة بالسلام، أمرها واسع، البُدأة بالسلام أمرها واسع. أما القَسْمُ: على الترتيب.","link":"https://binbaz.org.sa/fatwas/23876/بمن-يبدا-من-غاب-عن-زوجاته-ثم-حضر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/القسم بين الزوجات.mp3","categories":["تعدد الزوجات"]},{"id":3708,"question":"إذا أتحف واحدة دون الأخرى هل يكون هذا من غير العدل؟","title":"ما الذي يلزم التسوية فيه بين الزوجات؟","answer":"الجواب: الذي يظهر لي أنه لا بدّ من التسوية بينهما في النفقة ونحوها.\nس: إذا تزوج ثانية والأولى قد حج بها والثانية لم تحج ثم ذهب بالثانية هل يلزمه أن يحج بالأولى؟\nالشيخ: ما يظهر لي أنه يلزمه ما دام قد حجت فالحمد لله.","link":"https://binbaz.org.sa/fatwas/23899/ما-الذي-يلزم-التسوية-فيه-بين-الزوجات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/وجوب التسوية والعدل بين الزوجات.mp3","categories":["تعدد الزوجات"]},{"id":3709,"question":"إذا تزوج ثانية هل يعطي الأولى مثل مهر الثانية؟","title":"هل يلزم الزوج إرضاء زوجاته عندما يعدّد؟","answer":"الجواب: من الجهاز؟\nس: نعم.\nالشيخ: لا، ما يعطيها.\nس: ولا يلزمه شيء من هذا؟\nالشيخ: أبدًا، التسوية بينهم في القسم والنفقة.\nس: ما يعطيها من مسألة الرضاء يعطيها عشرة آلاف ؟\nالشيخ: هذا اصطلاح بينهم وإلا ما هو بلازم، الله أباح له التعدد إذا أعطاها....... فهذا من مكارم الأخلاق ومن التطمين وتخفيض ما أصابها من الشدة؛ لأنها يصيبها شدة عند وجود الزوجة الثانية، فإذا أعطاها بعض الشيء حتى يطمئن قلبها وترتاح بعض الراحة فهذا حسن....\nس: إذا اشترطت الأولى أنه لا بدّ أن يكون لها مبلغ معين من المال وإلا لا أرضى وأطلب الطلاق فهل يعطيها؟\nالشيخ: ما يلزمه، ترضى وإلا ما ترضى، واجب عليها أن ترضى، لكن هذا مكارم الأخلاق ومن تهدئة الأمور، كونه يعطيها، وإلا ما لها حق تُلزمه، ولا لها حق أن تطلب الطلاق، الله أباح له أربع هي إحداهن.","link":"https://binbaz.org.sa/fatwas/23900/هل-يلزم-الزوج-ارضاء-زوجاته-عندما-يعدد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسائل متفرقة في التعدد.mp3","categories":["تعدد الزوجات"]},{"id":3711,"question":"من يتزوج لأجل ثواب السنة، يقول: هذا سنة، وهو ليس بحاجة إلى ذلك، هو متزوج بكرًا، ولكن يقول هذه سنة؟","title":"حكم منْ يعدّد لأجل السنة وتحصيل الولد","answer":"الجواب: إذا استطاع لا بأس، له أربع.\nس: لأجل الثواب؟\nالشيخ: جزاه الله خيرًا، الله يثيبنا وإياه.\nس: بالنسبة للأولاد هل نقول: يستحب أن يتزوج أخرى حتى يحصل الولد؟\nالشيخ: الظاهر أنه مطلوب؛ لأن الرسول قال: تزوجوا الودود الولود فإني مكاثر بكم الأمم يوم القيامة فإذا تزوج بهذه النية فطيب، الثانية لأجل كثرة الولد أو ثالثة أو رابعة وهو يستطيع من دون مشقة؛ لا بأس وطيب.","link":"https://binbaz.org.sa/fatwas/23902/حكم-من-يعدد-لاجل-السنة-وتحصيل-الولد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من يعدد لأجل ثواب السنة ولتحصيل الولد.mp3","categories":["تعدد الزوجات"]},{"id":3840,"question":"إذا كان الزوج الثاني عِنِّينًا؟","title":"هل تَحِلُّ لزوجها الأول إذا كان الثاني عِنِّينًا؟","answer":"الجواب: لا تحل للأول حتى يطأها الثاني أو يطلقها ويتزوجها الآخر. المقصود حَتَّىٰ تَنكِحَ زَوْجًا آخر، كما قال الله، نكاحًا فيه جماع.","link":"https://binbaz.org.sa/fatwas/24043/هل-تحل-لزوجها-الاول-اذا-كان-الثاني-عنينا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا كان الزوج الثاني عنينًا، فهل تحل للأول.mp3","categories":["الشروط والعيوب في النكاح","تعدد الزوجات"]},{"id":5158,"question":"سائل يقول: رجل متزوج، وزوجته لا تعفّه؛ فكلما رأى أخرى فكأنه غير متزوجٍ، لأسبابٍ يعلمها الله، وزوجته قالت: إذا تزوجتَ طلقني، فهل يُعدد دون علمها ثم يُخبرها، مع أنها عصبية جدًّا، أم إذا وقفت عائقًا طلَّقها؟ وهل زواجه من الثانية يُعتبر واجبًا؛ لأنَّ زوجته الأولى لا تعفّه؟","title":"هل يجب التعدُّد على من لا تعفّه زوجته؟","answer":"الجواب: إذا كانت لا تعفّه فيلزمه النكاح إذا كان يقدر، فيتزوج ثانيةً، وإذا ما عفَّته الثانية يتزوج ثالثة، وإذا ما عفته الثالثة يتزوج رابعةً؛ حتى يعفَّ نفسه إذا كان يقدر وعنده مال، ولو ما رضيت الزوجة، لكن يُرضي الجميع بالكلام الطيب والأسلوب الحسن، والعدل. فعليه أن يتحرى العدل، ويسأل ربَّه أن يهديهنَّ، وأن يَمُنَّ عليهنَّ بالموافقة، ويجتهد، والحمد لله، مثلما قال جلَّ وعلا: فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلَاثَ وَرُبَاعَ فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا فَوَاحِدَةً [النساء:3]، ولا يجوز لهنَّ المُعارضة في هذا، فإن كانت لا تستطيع –يعني: عندها ضيقٌ، شدَّةٌ، ما تستطيع؛ تعطيه له.... تعطيه \"حل\"...","link":"https://binbaz.org.sa/fatwas/30079/هل-يجب-التعدد-على-من-لا-تعفه-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 102.mp3","categories":["تعدد الزوجات"]},{"id":5865,"question":"ما هو حكم تعدد الزوجات؟ هل هو أصل، أو رخصة؟ وما هي الضرورة التي تنطبق عليها هذه الرخصة إذا كانت رخصة؟","title":"هل تعدد الزوجات أصل أم رخصة؟","answer":"الجواب:  تعدد الزوجات قربة، وطاعة، وليست مجرد رخصة، تعدد الزوجات قربة، وطاعة، وعمل صالح في تكثير الأمة، وفي عفة الرجال، والنساء، وفيه القضاء على أسباب الفساد، والسفاح، قال الله -جل وعلا-: وَإِنْ خِفْتُمْ أَلَّا تُقْسِطُوا فِي الْيَتَامَى فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلَاثَ وَرُبَاعَ [النساء:3] فأمر به -جل وعلا- أمر بالنكاح مثنى، وثلاث، ورباع، ونبينا ﷺ تزوج تسعًا من النساء، مات عن تسع من  النساء، وتزوج مع ذلك امرأتين سابقتين، وعنده جاريتين، عليه الصلاة والسلام. فالمقصود: أن تعدد النساء أمر مطلوب مع القدرة عليه، ومع العدالة في ذلك، فإذا كان قادرًا، وعادلًا؛ فمشروع له أن يعدد حتى يكثر الأمة، وحتى يكون أعف لفرجه، وأعف لبصره، وحتى يعف من النساء من يسر الله له إعفافها، وحتى يكثر بسبب ذلك النسل، والأمة.  والنبي -عليه الصلاة والسلام- قال: تزوجوا الودود الولود، فإني مكاثر بكم الأمم يوم القيامة وفي لفظ: مكاثر بكم الأنبياء يوم القيامة فإكثار من يعبد الله في الأرض وهو يصلح في الأرض، ويقوم بالخلافة للرسل فيما دعوا إليه هذا خير عظيم، ونسأل الله أن يوفق المسلمين للهدى، والصلاح، والزوجات الصالحات، والأزواج الصالحين.  فإذا وجد الزوج الصالح، والزوجة الصالحة؛ فهو خير كثير، ومصلحة عظيمة، ولا يخفى أن الناس قد يبتلون بحروب، وأمراض، وغير ذلك، فتعدد الزوجات فيه مصالح كثيرة: الزوج يعف الله به فرجه، ونظره، فإن المرأة تبتلى بالمرض، وتبتلى بالحيض، والنفاس، تبتلى بأشياء تمنع الرجل من التمتع بها، فإذا كان عنده ثانية، وثالثة، ورابعة؛ انتفع بهذه، وهذه، وهذه في قضاء وطره، وفي عفة فرجه، وفي غض بصره، وهكذا النساء قد يبتلين بالفقر، قد يبتلين بالحروب، فإذا كان تحت زوج يقوم عليها، ويحسن إليها، ويعفها، ويحميها ربع زوج، أو ثلث زوج، أو نصف زوج خير لها من عدم ذلك. فالمصالح في هذا كثيرة مع العدالة، ومع الاستقامة، ومع تقوى الله، ومع النصح، ففي هذا خير كثير، أما مع الظلم، والعدوان لا يجوز ذلك، لكن يجوز، ويشرع مع العدالة، والاستقامة، والإنصاف من الزوج لهن، والعدل بينهن في الإنفاق عليهن، وفي جميع شؤونهن، والله المستعان.","link":"https://binbaz.org.sa/fatwas/1186/هل-تعدد-الزوجات-اصل-ام-رخصة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_181.mp3","categories":["قضايا المرأة","ردود وتعقيبات","الربا والصرف","تعدد الزوجات"]},{"id":5900,"question":"التي يريدها الرجل أن يشترطوا عليه طلاق الأولى، وهل يجوز له أن يقبل هذا الشرط دون سببًا من الأولى؟","title":"حكم اشتراط الزوجة الثانية طلاق الزوجة الأولى","answer":"الجواب: هذا لا يجوز، وبعض الناس يقولون: إذا خطب منهم آخر، وعند الخاطب زوجة، يقولون: بشرط أن تطلق زوجتك؛ هذا لا يجوز، الرسول ﷺ نهى عن ذلك، نهى أن تشترط المرأة طلاق أختها. فالحاصل: أنه لا يجوز للمخطوب منهم أن يشترطوا على الخاطب أن يطلق زوجته الحالية، بل هذا من ظلمهم، وعدوانهم، فليس لهم هذا الشرط، ولا يلزمه الوفاء لهذا الشرط؛ فإن هذا شرط منكر، فيخبرهم أن هذا لا يجوز، وأن الرسول نهى عن هذا الشرط، ولا يليق منكم ذلك، فإن صمموا، فشرطهم باطل، كما قال النبي ﷺ في قصة بريرة: كل شرط ليس في كتاب الله فهو باطل، وإن كان مائة شرط، قضاء الله أحق، وشرط الله أوثق.","link":"https://binbaz.org.sa/fatwas/1249/حكم-اشتراط-الزوجة-الثانية-طلاق-الزوجة-الاولى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_245.mp3","categories":["الشروط والعيوب في النكاح","تعدد الزوجات"]},{"id":6257,"question":"وآخر يقول: هل الأصل في الزواج واحدة، والتعدد جاء عارضًا لأسباب، أم هو العكس؟","title":"هل الأصل في الزواج التعدد؟","answer":"الجواب: الأصل التعدد، والواحدة هي التي يحصل بها عند العجز؛ لأن الله -جل وعلا- قال: وَإِنْ خِفْتُمْ أَلَّا تُقْسِطُوا فِي الْيَتَامَى فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلَاثَ وَرُبَاعَ فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا فَوَاحِدَةً [النساء:3] فدل على أن الأصل هو التعدد، يتزوج ثنتين، أو ثلاثًا، أو أربعًا؛ لأن هذا أقرب إلى إعفاف الرجل، وإلى كثرة النسل، فإذا عجز؛ اكتفى بواحدة، إن خاف أن لا يعدل؛ اكتفى بواحدة مع ما تيسر من الإماء.","link":"https://binbaz.org.sa/fatwas/1782/هل-الاصل-في-الزواج-التعدد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_621.mp3","categories":["الشروط والعيوب في النكاح","تعدد الزوجات"]},{"id":6266,"question":"وآخر يقول: هل الأصل في الزواج واحدة، والتعدد جاء عارضًا لأسباب، أم هو العكس؟","title":"هل الأصل في الزواج التعدد؟","answer":"الجواب: الأصل التعدد، والواحدة هي التي يحصل بها عند العجز؛ لأن الله -جل وعلا- قال: وَإِنْ خِفْتُمْ أَلَّا تُقْسِطُوا فِي الْيَتَامَى فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلَاثَ وَرُبَاعَ فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا فَوَاحِدَةً [النساء:3] فدل على أن الأصل هو التعدد، يتزوج ثنتين، أو ثلاثًا، أو أربعًا؛ لأن هذا أقرب إلى إعفاف الرجل، وإلى كثرة النسل، فإذا عجز؛ اكتفى بواحدة، إن خاف أن لا يعدل؛ اكتفى بواحدة مع ما تيسر من الإماء.","link":"https://binbaz.org.sa/fatwas/1782/هل-الاصل-في-الزواج-التعدد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_621.mp3","categories":["الشروط والعيوب في النكاح","تعدد الزوجات"]},{"id":6394,"question":"مع توفر الإمكانية، والعدل دون أن يكون هناك مبرر آخر أسمى من مجرد الشهوة؟","title":"حكم الزواج بأكثر من واحدة بنية قضاء الوطر","answer":"الجواب: يجوز أن يكون المبرر لتعدد الزوجات أن يقضي وطره إذا كانت الزوجة لا تعفه الواحدة؛ فلا مانع، بل قد تكون زوجتان أيضاً لا تعفه، والناس أقسام، وطبقات؛ فلا بأس أن يتزوج الثنتين، والثلاث، والأربع إذا دعت الحاجة إلى ذلك، وظن في نفسه العدل، والقيام بما يجب؛ فلا بأس بذلك، والله يقول -جل وعلا-: فَانكِحُواْ مَا طَابَ لَكُم مِّنَ النِّسَاء مَثْنَى وَثُلاَثَ وَرُبَاعَ فَإِنْ خِفْتُمْ أَلاَّ تَعْدِلُواْ فَوَاحِدَةً [النساء:3]. فلا بدّ أن يتزوج؛ ليجد الزوجة التي يحصل بها قضاء الوطر، والراحة إليها، والسكن إليها مع الزوجة الأولى، ومع الثانية، ومع الثالثة، والرابعة، هي النهاية.","link":"https://binbaz.org.sa/fatwas/1974/حكم-الزواج-باكثر-من-واحدة-بنية-قضاء-الوطر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_761.mp3","categories":["الشروط والعيوب في النكاح","تعدد الزوجات"]},{"id":6669,"question":"ألا يكون تعدد الزوجات سببًا لقلة راحة الرجل من خلال المشاجرات، وكره، وبغض الأولاد الذين هم من إحدى الزوجات من قبل الزوجة الأخرى سببًا يكره الأولاد آباءهم، أفتونا جزاكم الله خيرًا؟","title":"هل التعدد سبب للمشاكل","answer":"الجواب: هذا السؤال ناشئ عن تشبيه أعداء الله، وتلبيس أعداء الله، فليس هناك مشاكل، وليس هناك عداوة بين الأولاد، بل بينهم المحبة، والتعاون، والخير، وليس هناك مشاكل إلا من الزوج، هو هو صاحب المشاكل، فإذا عدل؛ فلا مشاكل.","link":"https://binbaz.org.sa/fatwas/2573/هل-التعدد-سبب-للمشاكل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1068.mp3","categories":["الشروط والعيوب في النكاح","تعدد الزوجات"]},{"id":6677,"question":"يقول تعالى: فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلَاثَ وَرُبَاعَ فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا فَوَاحِدَةً [النساء:3] ويقول في آية أخرى: وَلَنْ تَسْتَطِيعُوا أَنْ تَعْدِلُوا بَيْنَ النِّسَاءِ وَلَوْ حَرَصْتُمْ [النساء:129] فما تفسير ذلك؟","title":"الجمع بين آية التعدد وبين: {وَلَنْ تَسْتَطِيعُوا أَنْ تَعْدِلُوا}","answer":"الجواب: تقدم الجواب عن هذا، وأن الاستطاعة لا يمكن أن يقوم الإنسان بذلك، لكن عليه المستطاع، عليه ما يقدر، أما الحب -حب الإنسان في قلبه- فقد يحب هذه أكثر، وقد يجامع هذه أكثر، وقد يأنس بكلامها أكثر، فليس الأمر بيده، هذا يتعلق بالقلوب، وكان النبي يقسم بين نسائه -عليه الصلاة والسلام- ويقول: اللهم هذا قسمي فيما أملك، فلا تلمني فيما تملك، ولا أملك هكذا يقول النبي ﷺ قال العلماء: معناها الحب، والمودة، وما ينشأ عن ذلك ، هذه أمور بيد الله.","link":"https://binbaz.org.sa/fatwas/2574/الجمع-بين-اية-التعدد-وبين-ولن-تستطيعوا-ان-تعدلوا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1069.mp3","categories":["تعدد الزوجات","التفسير"]},{"id":6683,"question":"هل التعدد أصل في الشريعة، أم الواحدة؟ وهل العدل يعني كل شيء أو أشياء مخصصة؟","title":"التعدد هو الأصل في الشريعة","answer":"الجواب: الأصل التعدد، والواحدة عند العجز، والذين لا يعددون -ولاسيما من أعداء الإسلام هم أشباه الأنعام- يقتصرون على واحدة في الاسم، وهم في الحقيقة ليسوا على واحدة، بل على عدد كالتيس الذي يعرض عليه هذه وهذه، ويلقي منيه ونطفته في كل مكان ولا يبالي كالبهيمة، أما صاحب الزوجات في الشرع فهو يلقيها في محل صالح، في محل أباحه الله، في محل مخصوص، وهو بعيد عن مشابهة البهائم، ولكن هم -أعداء الله- أقرب الناس إلى مشابهة البهائم، كما قال : أَمْ تَحْسَبُ أَنَّ أَكْثَرَهُمْ يَسْمَعُونَ أَوْ يَعْقِلُونَ إِنْ هُمْ إِلَّا كَالْأَنْعَامِ بَلْ هُمْ أَضَلُّ سَبِيلًا [الفرقان:44]. السؤال: في الخارج يتزوج الرجل على واحدة امرأة، يقولون: عندهم القانون لا يبيح لهم أكثر من ذلك، وإذا أراد ان يتزوج؛ يتزوج متعة ما الحكم في هذا؟ الجواب: هذا عند الرافضة، المتعة عند الرافضة ما هي عند النصارى وأشباههم، النصارى عندهم الزنا.","link":"https://binbaz.org.sa/fatwas/2571/التعدد-هو-الاصل-في-الشريعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1066.mp3","categories":["الشروط والعيوب في النكاح","تعدد الزوجات"]},{"id":6725,"question":"استدلت بعض طوائف الشيعة على جواز الزواج بتسع، وأخذوا بالجمع بين الألفاظ الواردة في الآية مثنى، وثلاث، ورباع، ومجموعها تسع، فما رد سماحتكم؟","title":"الرد على من أجاز التزوج بتسع نسوة","answer":"الجواب: الرافضة قولهم لا يلتفت إليه، وهكذا من شذ من غيرهم، فقال بالتسع، كله قول مرفوض عند أهل العلم، وليس له نصيب من النصيحة، والذي عليه أهل العلم -وهو كالإجماع منهم- أنه لا يجوز أبدًا إلا أربع فقط، وأما التسع فهي خاصة بالنبي -عليه الصلاة والسلام- والرافضة لهم زلات كثيرة، وأخطاء كثيرة، وكثير منهم يبيح نكاح المتعة، وهو محرم بالنص من الرسول ﷺ وبإجماع أهل السنة، نكاح المتعة محرم عند أهل السنة، والجماعة، وبالنص عن رسول الله ﷺ فإنه لما حرم المتعة قال: فإن الله قد حرم ذلك إلى يوم القيامة وكثير من المرات كانوا يحلون المتعة، وربما تمتع بها وهي عندها زوج، ولا حول ولا قوة إلا بالله. المقصود: أن نكاح المتعة هو أن ينكحها على مدة شهرين، أو ثلاث، أو أربع إلى أجل معلوم، تمكنه من نفسها على شهرين، أو ثلاثة بدون ولي، وبدون شهود، هذا من أبطل الباطل، هذا هو الزنا، نسأل الله السلامة. السؤال: في صحيح البخاري عن أحد الصحابة  يقول: كنا مع الرسول في غزوة، فطالت علينا... ما معنى هذا الكلام؟ الجواب: يعني أباح لهم نكاح المتعةـ ثم نسخ المتعةـ كانت مباحة في أول الإسلام، ثم نسخها الله في آخر الإسلام، وحرمها، كان مباح لهم أن يتزوجون نكاح المتعة شهرين، ثلاثة، أربعة في الأسفار، ثم نسخ هذا، وحرمه الله إلى يوم القيامة.","link":"https://binbaz.org.sa/fatwas/2601/الرد-على-من-اجاز-التزوج-بتسع-نسوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1097.mp3","categories":["الشروط والعيوب في النكاح","تعدد الزوجات"]},{"id":6734,"question":"استدلت بعض طوائف الشيعة على جواز الزواج بتسع، وأخذوا بالجمع بين الألفاظ الواردة في الآية مثنى، وثلاث، ورباع، ومجموعها تسع، فما رد سماحتكم؟","title":"الرد على من أجاز التزوج بتسع نسوة","answer":"الجواب: الرافضة قولهم لا يلتفت إليه، وهكذا من شذ من غيرهم، فقال بالتسع، كله قول مرفوض عند أهل العلم، وليس له نصيب من النصيحة، والذي عليه أهل العلم -وهو كالإجماع منهم- أنه لا يجوز أبدًا إلا أربع فقط، وأما التسع فهي خاصة بالنبي -عليه الصلاة والسلام- والرافضة لهم زلات كثيرة، وأخطاء كثيرة، وكثير منهم يبيح نكاح المتعة، وهو محرم بالنص من الرسول ﷺ وبإجماع أهل السنة، نكاح المتعة محرم عند أهل السنة، والجماعة، وبالنص عن رسول الله ﷺ فإنه لما حرم المتعة قال: فإن الله قد حرم ذلك إلى يوم القيامة وكثير من المرات كانوا يحلون المتعة، وربما تمتع بها وهي عندها زوج، ولا حول ولا قوة إلا بالله. المقصود: أن نكاح المتعة هو أن ينكحها على مدة شهرين، أو ثلاث، أو أربع إلى أجل معلوم، تمكنه من نفسها على شهرين، أو ثلاثة بدون ولي، وبدون شهود، هذا من أبطل الباطل، هذا هو الزنا، نسأل الله السلامة. السؤال: في صحيح البخاري عن أحد الصحابة  يقول: كنا مع الرسول في غزوة، فطالت علينا... ما معنى هذا الكلام؟ الجواب: يعني أباح لهم نكاح المتعةـ ثم نسخ المتعةـ كانت مباحة في أول الإسلام، ثم نسخها الله في آخر الإسلام، وحرمها، كان مباح لهم أن يتزوجون نكاح المتعة شهرين، ثلاثة، أربعة في الأسفار، ثم نسخ هذا، وحرمه الله إلى يوم القيامة.","link":"https://binbaz.org.sa/fatwas/2601/الرد-على-من-اجاز-التزوج-بتسع-نسوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1097.mp3","categories":["الشروط والعيوب في النكاح","تعدد الزوجات"]},{"id":6755,"question":"ما حكم الزواج من بنت العم أو بنت الخال؟","title":"حكم الزواج من بنت العم والخال والجمع بينهما","answer":"الجواب: لا حرج في الزواج من بنت العم، وبنت الخال، الله أباح ذلك  ونكح النبي ﷺ ببنات عمه -عليه الصلاة والسلام- فالممنوع الأختين، الجمع بين الأختين، والجمع بين الخالة، وعمتها، والمرأة، وخالتها، هذا هو الممنوع، أما بنات العم، وبنات الخال؛ فلا بأس، وبنات الخالة، وبنات العمة؛ فلا حرج في زواجهن، والجمع بينهن.","link":"https://binbaz.org.sa/fatwas/2635/حكم-الزواج-من-بنت-العم-والخال-والجمع-بينهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1131.mp3","categories":["الشروط والعيوب في النكاح","تعدد الزوجات"]},{"id":6766,"question":"ما حكم الزواج من بنت العم أو بنت الخال؟","title":"حكم الزواج من بنت العم والخال والجمع بينهما","answer":"الجواب: لا حرج في الزواج من بنت العم، وبنت الخال، الله أباح ذلك  ونكح النبي ﷺ ببنات عمه -عليه الصلاة والسلام- فالممنوع الأختين، الجمع بين الأختين، والجمع بين الخالة، وعمتها، والمرأة، وخالتها، هذا هو الممنوع، أما بنات العم، وبنات الخال؛ فلا بأس، وبنات الخالة، وبنات العمة؛ فلا حرج في زواجهن، والجمع بينهن.","link":"https://binbaz.org.sa/fatwas/2635/حكم-الزواج-من-بنت-العم-والخال-والجمع-بينهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1131.mp3","categories":["الشروط والعيوب في النكاح","تعدد الزوجات"]},{"id":6949,"question":"كثيرًا ما نرى الإخوة الميسر لهم المال من المسلمين يقدمون على الزواج من الثانية، والثالثة، وهناك كثير من بلاد المسلمين، شباب مسلم، متدين، وفتيات مسلمات لا يجدن القدرة على الزواج بواحدة فقط؛ لعدم توفر المسكن الذي يؤويهما، وعدم القدرة على الإنفاق، أليس الأولى مساعدة هؤلاء الشباب، والشابات من المتدينين بالزواج، وعصمتهم من الوقوع في الإثم والمعصية؟","title":"حكم الزواج بأكثر من واحدة وهناك من لا يستطيع الزواج","answer":"الجواب: يقول النبي ﷺ: ابدأ بنفسك، ثم من تعول ابدأ بنفسك، ثم من تعول، إذا كنت أيها السائل نشيطًا؛ زوج من شئت من الناس، وتقتصر على واحدة -إذا كان يسدك الواحدة.  أما واحد ما تسده الواحدة، ولا تكفيه واحدة، يريد أن يعف نفسه، وأن يتباعد عن الحرام؛ فله أن يتزوج ثنتين، أو ثلاثًا.  ولو كان في باكستان، أو في أفغانستان، أو في مصر، أو في الشام، أو أنت في بلادك، شباب لم يستطيعوا الزواج، لا يلزمه تزويجهم، عليهم أن يعملوا، ويتزوجوا، وعلى أقاربهم أن يزوجوهم، أما هذا الشخص الذي محتاج للزوجة، ما يلزمه يزوج الآخرين، يبدأ بنفسه.","link":"https://binbaz.org.sa/fatwas/2879/حكم-الزواج-باكثر-من-واحدة-وهناك-من-لا-يستطيع-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1327.mp3","categories":["الشروط والعيوب في النكاح","تعدد الزوجات"]},{"id":6951,"question":"تعلمون سماحتكم أن الزوج يجد الكثير من العقبات في رعاية أبنائه الذين يتأثرون بعادات المجتمع من المدرسة، والشارع، وما يسمعه من زملائه الذين أثر فيهم الإعلام، ووسائله، والخادم الكافر، والسائق الكافر، والمربية الكافرة، وما ظهر من منكرات مثل: اللواط وترك الصلاة، والكذب إلى غير ذلك، الأمر الذي يتطلب من الوالد متابعة أولاده أولًا بأول، فكيف يستطيع الجمع بين تربية أبنائه، ومتابعتهم، وإصلاحهم، والإقامة مع زوجته الثانية، بعيدًا عن أولاده بمسكن آخر، لأسبوع، أو أكثر؛ ليحقق العدل بين الزوجات، نرجو من سماحتكم فتوانا في ذلك؟","title":"كيفية الجمع بين تربية الأبناء وبين الزوجة الثانية","answer":"الجواب: ما سمعت الله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286] عليه أن يتقي الله ما استطاع في تربية أولاده، وفي تشجيع إخوته، وأعمامه، أن يساعدوه، وأبنائه الكبار على تربية الصغار، فيتعاون مع أمهاتهم، ومع إخوته، ومع أعمامه، ومع أخوالهم؛ حتى يربوهم التربية الإسلامية فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. على المسلم أن يتعاون على البر والتقوى، وأن يبذل الوسع في ذلك، وهذا زمن غربة، أنت يا أخي الآن في زمن الغربة، نحن في عصر الغربة، بدأ الإسلام غريبًا، وسيعود غريبًا كما بدأ.  وأنواع الشر لا تحصى في كل بلاد، وفي غير هذه البلاد أكثر، في هذه البلاد شر كثير، وفي غيرها شر أكثر، فأنت الآن في زمن الغربة، فعليك أن تتقي الله، وأن تجاهد ما استطعت، وأن تعمل بالإصلاح ما استطعت، وليس تزوج الثانية هو الذي يعطل هذا الإصلاح.","link":"https://binbaz.org.sa/fatwas/2881/كيفية-الجمع-بين-تربية-الابناء-وبين-الزوجة-الثانية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1329.mp3","categories":["قضايا المرأة","تعدد الزوجات"]},{"id":6953,"question":"هل يحق للرجل أن يتزوج بأخرى بدون أي أسباب تدعو إلى ذلك؟","title":"حكم الزواج بامرأة ثانية بدون داعٍ","answer":"الجواب: نعم قال الله -جل وعلا-: فَانْكِحُوا مَا طَابَ لَكُمْ [النساء:3] طاب يعني ما شئتم، وما استحسنتم، فله أن يتزوج، ولو بأكثر؛ لأن هذا ينفعه بكل حال، لأن كبح الشهوة، والقيام بما يعين على كبح الغريزة الجنسية، وكثرة الأولاد، هذا مطلوب، وقد يتزوج لطلب الأولاد، وقد يتزوج لمزيد البعد عن أسباب الفتنة.","link":"https://binbaz.org.sa/fatwas/2883/حكم-الزواج-بامراة-ثانية-بدون-داع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1331.mp3","categories":["الآداب والأخلاق المحمودة","تعدد الزوجات"]},{"id":6955,"question":"هل تعدد الزوجات مباح فقط، أو هو سنة وردت عن الرسول ﷺ؟","title":"هل تعدد الزوجات مباح فقط أم سنة؟","answer":"الجواب: النص يقتضي أنها سنة، أقل الأحوال أنها سنة: فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ [النساء:3] أمر، لكن بشرط العدل، والاستقامة. وأما إذا خاف ألا يعدل لقلة ماله، أو لشيء يعرفه من نفسه من الضعف؛ فلا يتزوج إلا واحدة.","link":"https://binbaz.org.sa/fatwas/2885/هل-تعدد-الزوجات-مباح-فقط-ام-سنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1333.mp3","categories":["أصول الفقه","تعدد الزوجات"]},{"id":6956,"question":"يلاحظ في مجتمعنا المسلم ظاهرة خطيرة، وهي الإنكار على كل شخص يحاول أن يتزوج مرة ثانية، فأين دور العلماء الكرام في توعية هذا المجتمع؟ فأنا شاب مسلم، ومتزوج -ولله الحمد- أبحث عن زوجة أخرى، فلم أجد حتى أذنًا صاغية، فالكل يسفهني، فكيف نرضى ببعض الكتاب، ونعرض عن بعض؟","title":"القول فيمن ينكر على من أراد التعدد","answer":"الجواب: يسر الله أمرك، سمعت المحاضرة التي تؤكد ما قلته، وتأمر بالسماح، وهذا مما يتعلق بالعلماء، سمعت المحاضرة الآن، والتعليق عليها، وأنت -إن شاء الله- تعلق بعدين في المجتمعات؛ لأن القاعدة كما تقدم فليبلغ الشاهد الغائب.  سمعتم المحاضرة الآن، وسمعتم التعليق؛ فعليكم أن تبلغوا، فأنت واحد منهم فليبلغ الشاهد الغائب بلغوا من وراءكم من مجتمعاتكم، وأهليكم، وقبائلكم أن التعدد لا بأس به، وأنه مشروع مع تحري العدل، ومع تقوى الله في ذلك، وبلغوا النساء لا يأبين هذا، ويصبرن، ويحتسبن؛ حتى يكثر المتزوجون، وتقل العوانس، ويقل الشباب المتأخر عن الزواج، هذا إذا حضر التعاون مع الحرص على تخفيف المهور، وتقليل الولائم، يعني التناصح في هذا أن تكون المهور قليلة، وأن تكون الولائم قليلة؛ حتى لا يشق على الزوج، وحتى لا يكلف ما يمنعه من الزواج -نسأل الله للجميع التوفيق-.","link":"https://binbaz.org.sa/fatwas/2886/القول-فيمن-ينكر-على-من-اراد-التعدد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1334.mp3","categories":["الشروط والعيوب في النكاح","تعدد الزوجات"]},{"id":7300,"question":"أنا امرأة لي زوج وخمسة أبناء، ولكن زوجي متزوج من امرأة أخرى ويوليها اهتمامه أكثر مني ومن أبنائي، ويمنعني من أشياء يسمح بها للأخرى، وهذه حياتي معه، فما رأي سماحتكم بهذا الحال؟","title":"العدل بين الزوجات","answer":"الجواب: الواجب على الزوج أن يعدل فيما يتعلق بالزوجات، وليس له الحيف، هو مسؤول عن هذا الشيء، فالواجب على الأزواج أن يعدلوا بين الزوجات، وأن يستعينوا بالله، وأن يراقبوه  في كل شيء، في القسم، وفي النفقة، وفيما يتعلق بجبر الخواطر بينهن، وعدم إشاعة الشحناء بينهما.  هكذا ينبغي للزوج يكون حكيما وأن يحرص على كل ما يهدئ الأحوال ويجبر الخواطر، ويجعل الزوجتين فأكثر في راحة وفي طمأنينة من عدله وعنايته وحسن خلقه معهما جميعا، هذا هو الواجب عليه، وعلى الزوجات -ننصح الزوجات أيضا- بالتسامح في بعض الشيء وعدم التشديد وعدم التنقيب في كل الأمور، فإن من شدد لا بد يندم، ولا بد يفضي هذا التشديد إلى تحطيم الأسرة والعشرة بينهما إلا ما شاء الله، فينبغي للنساء أيضا التسامح في بعض الأمور وألا يشددن على الزوج فيما يتعلق بالعدل إذا كانت هفوة قليلة، أو شيء قليل ينبغي فيه التسامح والتغاضي، فلا بد من عناية من الزوج ولا بد من تسامح من الزوجات عن بعض الأشياء التي قد تقع من الزوج، وقد يكون غير عامد لها، وقد يكون مضطرا إليها، والمرأة لا ... الثانية، فينبغي للمرأة أن تسامحه في بعض الشيء؛ حتى يحصل الوئام، والتعاون على الخير.","link":"https://binbaz.org.sa/fatwas/3377/العدل-بين-الزوجات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1695.mp3","categories":["الآداب والأخلاق المحمودة","تعدد الزوجات"]},{"id":7434,"question":"رجل عنده أربع زوجات وجارية، وأنجبت الجارية، فهل يطلق واحدة، وهل إذا تزوج الجارية وأعتقها لا بد أن يطلق واحدة من الأربع؟","title":"حكم اقتناء جارية زيادة على أربع زوجات","answer":"الجواب: ليس له إلا أربع زوجات، وإذا كان عنده جارية مملوكة ما تحسب من الزوجات؛ لأن الله -جل وعلا- قال: فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا فَوَاحِدَةً أَوْ مَا مَلَكَتْ أَيْمَانُكُمْ [النساء:3] فالعدد من المماليك لا يضر، العدد إنما هو في الزوجات، في الأحرار أربع فأقل، ولو كان عنده معهن خمس إماء أو عشر إماء لا يضره، لكن إذا أعتقها، وجعل عتقها صداقها، وتزوجها؛ فلا بد أن تكون رابعة، ما تكون خامسة، إذا تزوجها على أنها خامسة ما يصلح، يبطل هذا العقد، ليس له إلا أربع.","link":"https://binbaz.org.sa/fatwas/3522/حكم-اقتناء-جارية-زيادة-على-اربع-زوجات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1826.mp3","categories":["الشروط والعيوب في النكاح","تعدد الزوجات"]},{"id":7683,"question":"سماحة الشيخ! هذه الرسالة وردت من مقدمها عبد الله الصالح ، يقول: أخي مقدم برنامج نور على الدرب أرجو عرض مشكلتي، أخي هناك مشكلة اجتماعية خطيرة استفحلت بسبب الغزو الاجتماعي تلك هي عدم تعدد الزوجات، فما رأيكم في ذلك؟","title":"مشروعية تعدد الزوجات في الإسلام","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فلا ريب أن تعدد الزوجات فيه مصالح جمة، وقد قال الله جل وعلا: وَإِنْ خِفْتُمْ أَلَّا تُقْسِطُوا فِي الْيَتَامَى فَانكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلاثَ وَرُبَاعَ فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا فَوَاحِدَةً أَوْ مَا مَلَكَتْ أَيْمَانُكُمْ [النساء:3]. \nفالله جل وعلا شرع لعباده تعدد الزوجات لمصالح كثيرة: منها ما في ذلك من عفة الرجل وعفة النساء، فإن الزواج من أسباب العفة، للرجل عما حرم الله، ومن أسباب عفة النساء عما حرم الله، وبقاء الرجل بلا زوجة أو معه زوجة لا تعفه؛ لأنه شديد الشهوة؛ قد يضره ويعرضه للفتن، وهكذا بقاء المرأة بدون زوج قد يعرضها للفتنة، فمن رحمة الله سبحانه أن شرع لعباده الزواج وشرع التعدد حتى يحصل من ذلك الخير الكثير، ومن أسباب ذلك أن الرجل قد لا تكفيه الواحدة، قد يكون قوي الشهوة فلا تكفيه الواحدة، فربما تعرض بسبب ذلك إلى ما حرم الله، فشرع الله له التعدد، ومن ذلك أيضاً أن المرأة تحيض ويصيبها النفاس أيضاً، فيتعطل الرجل مدة النفاس ومدة الحيض، فإذا كانت عنده ثانية وثالثة وجد ما يعفه عند تعطل المرأة وعند وجود ما يمنع الجماع، كذلك قد تمرض المرأة.. قد تسافر لبعض الأسباب، فالحاصل أن الحاجة إلى الثانية والثالثة والرابعة حاجة ظاهرة. \nكذلك قد يكثر النساء ويتعطلن من أزواج، فكونهن عند زوج يعفهن ويقوم عليهن وينفق عليهن ويصونهن، ولو كن أربعاً تحت واحد هذا خير لهن من تعطلهن وعدم التزوج. \nفالذي جاءت به الشريعة كله خير وكله صلاح للمجتمع، فلا ينبغي لعاقل أن يستنكر ذلك، وإن كان بعض النساء قد يستنكرن ذلك لقلة الفهم وقلة البصيرة وقلة العلم، وإلا فالتعدد فيه مصالح للجميع للرجال والنساء جميعاً، ولكن بعض النساء قد يجحد هذا الشيء وقد ينكر هذا الشيء ويرغب السلامة وذلك من عدم النظر في العواقب ومن عدم البصيرة في الدين. \nفلا ينبغي للمرأة أن تستنكر هذا الشيء، نعم لا بأس إذا سلمت من الضرة لا بأس، ولكن لا يجوز لها أن تستنكر حكم الله، ولا أن تكره حكم الله، بل عليها أن ترضى بحكم الله، وأن تعلم أن حكم الله فيه الخير للجميع، وفيه السعادة للجميع ولو حصل عليها بعض الأذى من الجارة، أو انفردت في بعض الليالي لا يضرها ذلك، والحمد لله ما دام الأمر على شرع الله وفيه مصالح كثيرة فينبغي لها التحمل والتصبر وعدم الاستنكار للزوج الذي عنده أكثر من واحدة، بل إذا تيسر لها زوج ليس معها فيه شريك فلا بأس، وإلا فلا ينبغي أن تصبر على الوحدة والبقاء بدون زوج من أجل عدم الجارة، بل ينبغي لها أن تصبر وأن تنكح الزوج اللي معه زوجة قبلها أو زوجتان، ولا بأس عليها في ذلك إذا عدل. نعم.","link":"https://binbaz.org.sa/fatwas/4882/مشروعية-تعدد-الزوجات-في-الاسلام ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_027/02701.mp3","categories":["تعدد الزوجات"]},{"id":7684,"question":"هناك أيضاً بعض النساء يفضلن العادات الاجتماعية في أوروبا أو في الغرب عموماً أو في البلاد غير الإسلامية، ويقلن في ذلك: إن تعدد الزوجة ممنوع، وهنا مثلاً في الحكم الشرعي يباح تعدد الزوجة، فما الحكم في إلصاق هذه التهمة في الإسلام؟","title":"حكم من أنكر تعدد الزوجات","answer":"الجواب: من كره تعدد الزوجات وزعم أن عدم التعدد أفضل، فهو كافر مرتد عن الإسلام؛ لأنه -نعوذ بالله- منكر لحكم الله وكاره لما شرع الله، والله يقول سبحانه: ذَلِكَ بِأَنَّهُمْ كَرِهُوا مَا أَنزَلَ اللَّهُ فَأَحْبَطَ أَعْمَالَهُمْ [محمد:9]، من كره ما أنزل الله حبط عمله، فالذي يكره تعدد الزوجات ويرى أن الشريعة يعني قد ظلمت أو أن في حكم الله في هذا ناقص أو مو بطيب، أو أن ما يفعلونه في بلاد النصارى من الواحدة أن هذا أولى وأفضل، هذا كله ردة عن الإسلام نعوذ بالله، كالذي يقول: إن فرض الصلاة ما هو مناسب، لو ترك الناس بدون الصلاة كان أحسن أو بدون صيام أحسن أو بدون زكاة، من قال هذا فهو كافر، من قال: إن عدم الصلاة أولى أو عدم الصيام أولى أو عدم الزكاة أولى أو عدم الحج أولى كان كافراً، وهكذا لو قال: لا بأس أن يحكم بغير الشريعة، يجوز، ولو قال: حكم الشريعة أفضل، لكن إذا قال: إن الحكم بغير ما أنزل الله جائز أو أنه حسن، كل هذا ردة عن الإسلام نعوذ بالله. \nفالحاصل من كره ما أنزل الله وما شرعه الله هو مرتد، وهكذا من أحب ورضي بما حرم الله وقال: إنه طيب وإنه مناسب كالزنا والسرقة يكون كافراً أيضاً .نعم. نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/4883/حكم-من-انكر-تعدد-الزوجات ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_027/02702.mp3","categories":["تعدد الزوجات"]},{"id":7936,"question":"من المرسل أحمد عبد الله جاد من بورما، يقول: السلام عليكم ورحمة الله وبركاته، أرجو عرض هذا السؤال على فضيلة الشيخ عبد العزيز بن باز ، وإذاعة الرد مع جزيل الشكر، يقول: ابتليت بزوجة تكره المعاشرة الزوجية أي: الجنس، ولا تعرف حقوق الزوج وتنام في غرفة أخرى، ولا تعرف الزينة ونصحتها وأرشدتها ووجهتها، ولكن دون جدوى، فهل إذا تزوجت بأخرى وهجرتها أؤثم، علماً بأن لي منها أولاد وبنات على المدى الطويل ولا سبيل لإصلاحها أفيدوني جزاكم الله خير؟","title":"كيفية العمل مع المرأة التي لا تحسن معاشرة زوجها","answer":"الجواب: الواجب على المرأة السمع والطاعة لزوجها في المعروف، والواجب عليها أن تحسن العشرة، وأن تمكنه من نفسها إذا أراد قضاء حاجته منها، وأن تخاطبه بالتي هي أحسن، وأن تنام معه في الفراش إذا طلب ذلك، هذا هو الواجب عليها؛ لأن الله يقول : وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ [البقرة:228] لهن من المعاشرة الطيبة مثل الذي عليهن، الله أمر بالمعاشرة الطيبة فقال: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] فكما يجب على الزوج أن يعاشر بالمعروف فهي أيضاً عليها أن تعاشر بالمعروف، وللرجال على المرأة درجة، فعلم بذلك أن حق الرجل أكبر، وأن الواجب عليهما جميعاً التعاون على البر والتقوى والمعاشرة الطيبة بالكلام الطيب والفعل الطيب، عليها وعليه جميعاً، فإذا أصرت على أنها لا تمكنه من نفسها وعلى أنها تنفرد وحدها، وعلى أنها لا تعتني بنفسها من جهة الزينة والطيب، فهذا غلط منها وخطأ لا يجوز لها ذلك.\nولك -أيها السائل- أن تتزوج مطلقا، لك أن تتزوج بثانية وثالثة ورابعة لا حرج عليك، حتى ولو كانت من أحسن الناس طاعة وامتثالاً، لك أن تتزوج، لكن بهذه المثابة من باب أولى أن تتزوج؛ لأنها لم تقم بالواجب، ولم تمكنك مما يسبب عفتك وغض بصرك، فالمشروع لك في هذه الحال وأنت قادر أن تتزوج حتى تعف نفسك، وحتى تجد الراحة من هذا التعب، ولعلها بالزواج لعلها تنيب إلى رشدها، ولعلها ترجع عن غلطها هذا بسبب زواجك على غيرها، هذا هو الذي أرى في هذه المسألة، مع النصيحة لها والعناية بها وتوجيهها إلى الخير، وكذلك توصي أقاربها كأبيها وأخيها أو خالها أو عمها أن ينصحها وأن يوجهها إلى الخير، وكذلك أمها وجدتها وخالاتها يعني توصي من حولك من أقاربها بأن ينصحوها ويوجهوها إلى الخير؛ لأن هذا أمر يضرها ويضرك جميعا، ويضركما جميعاً، فإن استمعت واستقامت فالحمد لله، وإلا فأنت حر بحمد الله تستطيع أن تفارقها، تستطيع أن تتزوج ثانية وثالثة ورابعة، كل هذا بحمد الله لك ميسر إذا قدرت عليه، والله المستعان، ونسأل الله للجميع الهداية.","link":"https://binbaz.org.sa/fatwas/5457/كيفية-العمل-مع-المراة-التي-لا-تحسن-معاشرة-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_066/06606.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":7945,"question":"هذه الرسالة -يا سماحة الشيخ- وردتنا من مقدم الأسئلة المستمع (ع. س. م) من الرياض يقول فيها: السلام عليكم ورحمة الله وبركاته.. وبعد:رجل مريض بشلل نصفي وتأتي الصرعة مرة واحدة في كل شهر -ربنا يحفظنا ويحفظكم من هذا المرض- وله رغبة في معاشرة وجماع زوجته ولكن زوجته ترفض ذلك وتقول: إذا أنا أنجبت أولاد معك فإنني كالذي زنت، ما حكم الشريعة في تلك الزوجة وفقكم الله؟","title":"حكم رفض المرأة معاشرة زوجها المصاب بالصرع","answer":"الجواب: الواجب عليها أن تمكنه من نفسها؛ لأنها زوجته وعليها أن تمكنه من نفسها، فإذا كانت يعني قد كرهته من أجل الصرع فترفع أمرها إلى الحاكم ما دامت في عصمته وزوجته فله الحق أن يجامعها ويتصل بها وعليها الحق أن تمكنه من نفسها، أما إذا كانت لما أصابه الصرع كرهته وأحبت الفراق فهذا يرجع إلى المحكمة، لكن إذا كانت قد رضيت واستقرت معه والصرع معه فإنه يلزمها أن تمكنه من نفسها حتى يقضي وطره من ذلك، وإن كانت حرمت وقالت: عليها الحرام وهي زانية إذا مكنته من نفسها فعليها كفارة اليمين، إذا كانت حرمت أن تمكنه من نفسها فهذا في حكم اليمين وعليها كفارة اليمين: إطعام عشر مساكين إذا كانت حرمت ذلك، وأما إذا كانت لم تحرم فعليها أن تمكنه من نفسها ولا بأس عليها في ذلك ولا حرج؛ لأن الصرع يعرض ويزول، أما إذا كانت كرهته وتريد فراقه فهذا إلى المحكمة والمحكمة تنظر في ذلك.","link":"https://binbaz.org.sa/fatwas/5477/حكم-رفض-المراة-معاشرة-زوجها-المصاب-بالصرع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_068/06808.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":8046,"question":"هذه رسالة وردتنا من المستمع يقول: من الجمهورية العراقية محافظة نينوى، الأخ خ م أ يقول: ما حكم من يقبل نهود زوجته أي: الثدي، ويقوم بعض رءوس الثدي أثناء بداية الزواج وكذا ... إلى آخره، هل في ذلك شيء أم لا؟","title":"حكم تقبيل ثدي الزوجة وعضه من باب المداعبة","answer":"الجواب: لا نعلم في هذا شيء، أقول: لا نعلم في تقبيل الثدي أو عضه ما فيه شيء، أو مصه مصاً هكذا من باب المداعبة، أما شرب اللبن والحليب الذي فيه تركه أوْلى، ترك شرب اللبن أوْلى نعم، وأما مجرد التقبيل أو مص النهد من دون شيء، أو عض اللعب وما فيه شيء يؤذي: ما نعلم فيه شيء. نعم.","link":"https://binbaz.org.sa/fatwas/5845/حكم-تقبيل-ثدي-الزوجة-وعضه-من-باب-المداعبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_081/08111.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":8088,"question":"أخونا (ن. م. أ. ن) من الرياض يسأل أيضاً ويقول: والدي قام بالزواج من امرأة أجنبية وترك منزلنا وترك لي في المنزل والدتي وأربعة إخوة وذلك قبل ستة أعوام، ولقد قمت بفضل من الله وتوفيقه برعايتهم وتربيتهم والإنفاق عليهم، حيث أن والدي كان يقوم بإرسال مبلغ بسيط لا يكفي لإعالتنا وذلك في أوقات متباعدة، مثلاً: أن يرسل النفقة لمدة ثلاثة أشهر ثم يقوم بقطعها، فأقوم بالاتصال بوجوه الخير، ويقومون بدورهم بإقناعه بإرسال النفقة وذلك يستغرق شهوراً بل قد يصل إلى سنة، علماً بأنه قد فتح الله علينا وعلى والدنا واسع الثراء، ولقد قام في هذه الأيام بمطالبة والدتي بالذهاب إليه مصطحبة معها الأطفال الصغار رغم رفض الجميع لذلك، وحيث أنه قد انتفت العشرة الحسنة والمعروف بينهما رفضت والدتي بالذهاب إليه، فهل يحق لها أن تظل معي؟ وهل يحق لها السفر أو الخروج من المنزل دون رأي الوالد حيث أنه ومنذ أن ترك الوالد المنزل تقوم والدتي بسؤالي في هذه الأمور، أرجو أن توضحوا لنا عن كل ذلك ولكم الأجر والثواب؟","title":"حكم من ترك زوجته وأولاده ثم طالبهم بالعودة إليه","answer":"الجواب: ما دام الوالد لم يطلق فإن عليها أن تسمع وتطيع وتخرج معه حيث أراد إذا أسكنها في محل مناسب ومسكن مناسب ولا يلزمها أن تكون مع ضرتها في مسكن واحد إلا إذا كان المسكن واسعاً بحيث يكون لكل واحدة شقة تخصها فلا بأس وليس لها أن تعصيه، وما مضى من التساهل ينبغي فيه التسامح، وإذا طلبت نفقتها الماضية فلها حق إن أعطاها ذلك وإلا فلها أن تطالبه لدى المحكمة، وإن سمحت فهو خير وما عند الله خير وأبقى، والتسامح من أسباب دوام العشرة ومن أسباب طيب الخواطر وعدم تأثر أبيك عليها، فالأولى والذي ننصح به أنها تسمح عما مضى وتنتقل مع الزوج حيث أراد إذا أسكنها في المحل المناسب، وما مضى يعفو الله عنه من الجميع ينبغي فيه التسامح، هذا هو الذي ننصح به.\nأما مسائل النزاع والخصومات هذا عند المحاكم، لكن هذا ننصح به أمك أن تسمع وتطيع لزوجها وأن لا تأخذه بالماضي ولها حق في الماضي من جهة النفقة، وإذا كنت قمت بنفقتها بالنيابة عن أبيك فالحمد لله.\nالمقدم: بارك الله فيكم. هل من كلمة إلى مثل هذا الزوج سماحة الشيخ؟\nالشيخ: نعم، ننصح الزوج هذا بأن يتقي الله وأن يحسن إليها، وأن يعدل بينها وبين ضرتها، وأن يعطيها ما يسمح خاطرها عما مضى من الهجر والتساهل وعدم الإنفاق، هذا هو الذي ننصحه به؛ لأن النفوس يعتريها ما يعتريها عند الإهمال والإضاعة والهجر، فينبغي له أن يفعل ما يطيب النفس ويزيل ما في النفس من جهة أم أولاده، ونسأل الله للجميع الهداية والتوفيق، وهذا أولى من المحاكمة والمخاصمة.","link":"https://binbaz.org.sa/fatwas/5884/حكم-من-ترك-زوجته-واولاده-ثم-طالبهم-بالعودة-اليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_101/10102.mp3","categories":["تعدد الزوجات"]},{"id":8158,"question":"الرسالة التالية وصلت إلى البرنامج من العراق نينوى وباعثتها الأخت: حفصة يونس محمد ، أختنا تسأل مجموعة من الأسئلة، من بينها سؤال عن عمها الذي تزوج بامرأة جديدة فلم يهتم إلا بها وبأولادها وترك أولاد زوجته الأولى، الرأي لو تكرمتم سماحة الشيخ؟","title":"اهتمام الزوج بإحدى زوجتيه دون الأخرى","answer":"الجواب: الواجب نصيحته، الواجب نصيحته من إخوته ومن أصدقائه ينصحونه حتى يحسن في أم أولاده الأولى، وحتى يعرف لها حقها وفضلها، وأن لا ينساها ويعرض عنها ويبخسها حقها، فإن كان ولابد وليس له رغبة فيها فإنه يخيرها: إن شاءت صبرت على ما يسر الله منه وإن شاءت طلبت الطلاق، فإن طلبت الطلاق وجب عليه أن يطلق أو يعدل بينها وبين الجديدة، وليس له أن يحبسها ولا يعدل بل عليه أن يعدل بينهما أو يجيبها إلى طلب الطلاق فيطلق، وإذا طلقها أنفق عليها نفقة العدة طلقها طلقة واحدة السنة، أن يطلق واحدة فقط لا يطلق بالثلاث يطلق واحدة وينفق عليها نفقة العدة ويعرف لها فضلها، الله يقول: وَلا تَنسَوُا الْفَضْلَ بَيْنَكُمْ [البقرة:237].\nفينبغي له أن لا ينسى حالها الأولى وأنها أم أولاده، فينبغي له أن يكرمها ويلاحظها ويطيب خاطرها بما تيسر له من المساعدة هكذا ينبغي للرجال الأخيار ذوي مكارم الأخلاق وذوي النفوس الرفيعة الطيبة، ولكن لا يلزمه أن يبقيها في حباله إذا شاء أن يطلق فله أن يطلق، وإن صبرت هي ولم تطلب الطلاق رجاء أن يعود إليها أو لأنها ليست في حاجة إلى الطلاق لأنها لا ترغب الزواج على غيره، فإذا صبرت فلا بأس، وهو ينبغي له أن يحسن إليها وأن يعرف لها حالها الأولى، وأن يجود عليها بما يسر الله له ولا ينساها، هذا هو المشروع له.\nوعلى أقاربه الطيبين أن ينصحوه حتى يعدل أو يطلق إذا طلبت الطلاق.\nنعم والله ولي التوفيق.","link":"https://binbaz.org.sa/fatwas/5961/اهتمام-الزوج-باحدى-زوجتيه-دون-الاخرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_104/10403.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":8164,"question":"الرسالة التالية وصلت إلى البرنامج من العراق نينوى وباعثتها الأخت: حفصة يونس محمد ، أختنا تسأل مجموعة من الأسئلة، من بينها سؤال عن عمها الذي تزوج بامرأة جديدة فلم يهتم إلا بها وبأولادها وترك أولاد زوجته الأولى، الرأي لو تكرمتم سماحة الشيخ؟","title":"اهتمام الزوج بإحدى زوجتيه دون الأخرى","answer":"الجواب: الواجب نصيحته، الواجب نصيحته من إخوته ومن أصدقائه ينصحونه حتى يحسن في أم أولاده الأولى، وحتى يعرف لها حقها وفضلها، وأن لا ينساها ويعرض عنها ويبخسها حقها، فإن كان ولابد وليس له رغبة فيها فإنه يخيرها: إن شاءت صبرت على ما يسر الله منه وإن شاءت طلبت الطلاق، فإن طلبت الطلاق وجب عليه أن يطلق أو يعدل بينها وبين الجديدة، وليس له أن يحبسها ولا يعدل بل عليه أن يعدل بينهما أو يجيبها إلى طلب الطلاق فيطلق، وإذا طلقها أنفق عليها نفقة العدة طلقها طلقة واحدة السنة، أن يطلق واحدة فقط لا يطلق بالثلاث يطلق واحدة وينفق عليها نفقة العدة ويعرف لها فضلها، الله يقول: وَلا تَنسَوُا الْفَضْلَ بَيْنَكُمْ [البقرة:237].\nفينبغي له أن لا ينسى حالها الأولى وأنها أم أولاده، فينبغي له أن يكرمها ويلاحظها ويطيب خاطرها بما تيسر له من المساعدة هكذا ينبغي للرجال الأخيار ذوي مكارم الأخلاق وذوي النفوس الرفيعة الطيبة، ولكن لا يلزمه أن يبقيها في حباله إذا شاء أن يطلق فله أن يطلق، وإن صبرت هي ولم تطلب الطلاق رجاء أن يعود إليها أو لأنها ليست في حاجة إلى الطلاق لأنها لا ترغب الزواج على غيره، فإذا صبرت فلا بأس، وهو ينبغي له أن يحسن إليها وأن يعرف لها حالها الأولى، وأن يجود عليها بما يسر الله له ولا ينساها، هذا هو المشروع له.\nوعلى أقاربه الطيبين أن ينصحوه حتى يعدل أو يطلق إذا طلبت الطلاق.\nنعم والله ولي التوفيق.","link":"https://binbaz.org.sa/fatwas/5961/اهتمام-الزوج-باحدى-زوجتيه-دون-الاخرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_104/10403.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":8922,"question":"الرسالة التالية وصلت إلى البرنامج من البحرين، باعثها أحد الإخوة من هناك يقول: أبو إبراهيم، أخونا له مجموعة من الأسئلة من بينها سؤال يقول: أرغب في الزواج من امرأة ثانية وأنا قادر على تكاليف الزواج وعلى الصرف على بيتين، وأجد في نفسي أنني أستطيع أن أعدل بين الزوجتين، لكني سمعت من بعض الإخوة أن زواج الثانية لابد له من شروط، كأن تكون الزوجة الأولى مريضة أو لا تنجب أو غير ذلك من الأسباب، فهل هذا صحيح أو أنه في الإمكان أن أعدد من غير سبب ما دمت قادراً وأجد في نفسي الاستطاعة على العدل بين الزوجتين، وماذا يرى سماحتكم في هذا الموضوع ولاسيما التعدد خاصة، جزاكم الله خيراً؟","title":"هل يتزوج الثانية دون عيب أو نقص في الأولى","answer":"الجواب: لا مانع من التعدد وإن كانت الزوجة الموجودة صالحة وطيبة ليس فيها مرض ولا علة ولو كانت تنجب لا حرج في ذلك إذا كنت بحمد الله قادراً على الزواج وعلى العدل فالحمد لله، الله يقول سبحانه: فَانكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلاثَ وَرُبَاعَ فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا فَوَاحِدَةً أَوْ مَا مَلَكَتْ أَيْمَانُكُمْ [النساء:3]، والنبي ﷺ تزوج عدة من النساء عليه الصلاة والسلام وليس في أزواجه علة.\nفالمقصود أنه ﷺ تزوج وهكذا الصحابة تزوجوا، منهم من تزوج ثنتين وتزوج ثلاث، ومنهم من تزوج أربع، فالأمر في هذا واسع والحمد لله، إنما المؤمن يحرص أن يعدل ويجتهد في العدل بين الزوجتين أو الثلاث أو الأربع، والزواج فيه مصالح؛ فيه عفة الفرج وعفة النظر وفيه كثرة النسل، وفيه إحسان للنساء أيضًا حتى النساء فيه إحسان إليهن، فإن وجود نساء ليس لهن أزواج هذا من المصائب وفيه خطر، فكون المرأة تعطى نصف زوج، يعني: يحصل لها نصف أو ثلث أو ربع يعفها وينفق عليها ويحصل لها بسببه النسل هذا خير عظيم ومصلحة كبيرة، خير من بقائها في البيت بدون زوج، فكونها يحصل لها ربع الزوج أو ثلثه أو نصفه خير من بقائها في بيتها بدون زوج لوجوه كثيرة ومصالح جمة للزوج والزوجة جميعًا من كثرة النسل وعفة فرجها وعفة فرجه، وغض بصرها وغض بصره، وإيناسها في هذه الدنيا وقضاء وطرها وقضاء وطره، فالمصالح كثيرة، ومن ذلك تكثير الأمة، فإن وجود النسل بين الزوجين من زوجتين أو أكثر أكثر للأمة، والنبي ﷺ قال: تزوجوا الولود الودود فإني مكاثر بكم الأمم يوم القيامة.\nفالمطلوب تكثير الأمة، تكثير الأولاد الصالحين من الرجال والنساء، فالمؤمن يجتهد ويسأل الله التوفيق. نعم.\nالمقدم: جزاكم الله خيرًا، بالرغم من أن شطر هذه الكلمة موجه للنساء جزاكم الله خيرًا سماحة الشيخ إلا أني أجد في نفسي الرغبة أكثر ولاسيما وقد قرأت كثيراً عن تعدد العوانس في البيوت؟\nالشيخ: من المصائب أن كثيرًا من الناس اليوم يدعو إلى عدم التعدد وربما اغتروا بما يقوله بعض النصارى ومن شابه النصارى في ذلك، وكثير منهم يحبذ أن يكون الزوج باقياً على واحدة ويندد بالأزواج الذين يعددون وهذا كله غلط، وكله تشبه بالنصارى ، أو تأثر بما قالوه أو قاله من التحق بهم أو شاركهم في رأيهم أو اقتدى بهم في أخلاقهم، والشريعة الإسلامية العظيمة جاءت بالتعدد وكان التعدد قبلنا أكثر، كان عند داود مائة امرأة عليه الصلاة والسلام، وتزوج سليمان تسعاً وتسعين، في رواية: سبعين، كان التعدد في شريعة التوراة أكثر أما في شريعة محمد ﷺ فاقتصر العدد على أربع فأقل للأمة ما عدا النبي ﷺ فله تسع عليه الصلاة والسلام، هذا من رحمة الله جل وعلا أن جعل العدد أربعًا فأقل في هذه الأمة لحكمة بالغة، أما مصالح التعدد فشيء لا يحصى، مصالح التعدد فيه شيء واضح، المصالح كثيرة للرجال والنساء، النساء يحصل لهن العفة وقضاء الوطر والإنفاق عليهن، ودخول الزوج عليهن واحترامهن، والدفاع عنهن وهيبة الرجل إذا دخل عليها، وسلامتها في الأغلب من تعلق غيره بها، إلى غير ذلك من المصالح، ثم الإنفاق عليها ثم وجود الولد الذي يهبها الله ولدًا على يديه فيحصل لها بذلك خير عظيم إذا أصلح الله الولد، وقد يكون عدة أولاد من الرجال والنساء، فالمصالح كثيرة، فهو ينتفع وهي تنتفع، والأسرة كلها تنتفع، فإن كثرة النسل فيه نفع للجميع وتكثير للأمة، كما أن في ذلك صيانة لها وحماية لها وعفة لفرجها وإنفاقًا عليها وإحسانًا إليها، وحرصاً على كل ما يصونها من كل بلاء و شر. نعم.\nالمقدم: بارك الله فيكم، بعض النساء سماحة الشيخ تعتقد أن الزواج من أجل النفقة فقط، فإذا كانت موظفة ولها دخل أو لها تجارة أو كذا لا تريد إلا رجلا خاليًا؟\nالشيخ: هذا غلط، هذا من الغلط، الزواج يراد منه مصالح كثيرة:\nيراد منه طيب العشرة بين الزوجين والأنس في هذه الدنيا والتمتع بينهما المتعة الحسنة الصالحة فيما بينهما.\nويراد منه أيضاً إنجاب الأولاد الصالحين حتى تكثر الأمة ويكثر فيها الصلاح والخير.\nويراد منه أيضاً عفة الفرج عما حرم الله وعفة النظر عما حرم الله.\nويراد من ذلك أيضاً تقليل الفساد في الأرض فإن وجود الرجال والنساء بدون زواج من أعظم الأسباب للفساد في الأرض وكثرة الزنا والفواحش، فإذا تزوجت وتزوج الشاب صار هذا من أعظم الأسباب للصيانة والحماية وقلة الفساد في الأرض، فالزواج ينفع هذا وهذا، ولهذا قال ﷺ: يا معشر الشباب! من استطاع منكم الباءة فليتزوج فإنه أغض للبصر وأحصن للفرج، ومن لم يستطع فعليه بالصوم فإنه له وجاء .\nفالزواج فيه خير للجميع لا مجرد النفقة فقط، فيه مصالح كثيرة غير النفقة. نعم.\nالمقدم: بارك الله فيكم، بعض الأزواج سماحة الشيخ أساء إلى مبدأ التعدد؟\nالشيخ: لا شك أن الزوج إذا لم يعدل أساء إلى التعدد وأساء إلى الشريعة وأساء إلى المسلمين، فالواجب على الزوج أن يتقي الله وأن يحسن فيما عليه وأن يؤدي الواجب وأن يكون حريصاً على العدل بين الزوجتين فأكثر حتى لا يظلم نفسه وحتى لا يسبب النفرة من التعدد بأسباب عمله، وحتى أيضاً لا تقع المشاكل بين الأسرتين وتكثر الخصومات في المحاكم، هذا كله يسبب المشاكل، أما العدل والإحسان وطيب العشرة فهو يسبب الخير الكثير للأسرتين وللمجتمع كله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7079/هل-يتزوج-الثانية-دون-عيب-او-نقص-في-الاولى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_142/14203.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":8983,"question":"نعود في هذه الحلقة سماحة الشيخ إلى رسالة الأخ: بابكر آدم سليمان سوداني أخونا عرضنا جزءًا من أسئلته في حلقة مضت وفي هذه الحلقة يقول: أنا متزوج ومستقر بمنطقة، ولي عمل بمنطقة أخرى تبعد حوالي مسافة يومين بالسيارة، وحصل أن تزوجت بمنطقة عملي وكنت أقيم في مكان عملي زهاء شهرين أو ثلاثة وإذا أتيت إلى مكان استقراري أقيم حوالي أسبوع أو أسبوعين فهل هذا صحيح أم فيه مخالفة للشريعة في العدل بين الزوجات؟","title":"كيف يعدل وله زوجتان في منطقتين متباعدتين","answer":"الجواب: الواجب عليك أن تعدل بينهما حسب الطاقة والإمكان، فتنقل التي في مستقرك إلى محل عملك حتى تعدل بينهما أو تنقل الجديدة إلى محلك الأول حتى تعدل بينهما، أو تستسمحهما، فإذا سمحت الأولى ولم تلحقها حرجًا فلا بأس بذلك الحق لهما، فإذا سمحت الأولى عن بعض حقها فلا بأس.\nالمقصود أن عليك أن تتحرى العدل حسب طاقتك، إما بنقل الأولى إلى محل عملك، أو نقل الثانية إلى محل أصلك إلى محل بلدك الأولى حتى تجمع بينهما هناك وحتى تعدل بينهما، أو تستسمح الأولى عما يحصل عليها من النقص، فإذا سمحت فالحمد لله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7141/كيف-يعدل-وله-زوجتان-في-منطقتين-متباعدتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_174/17408.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":9463,"question":"هذه رسالة وردت من السائلة: (م. ن. ر) من الخبر في المملكة، تقول هذه السائلة في رسالتها: أنا امرأة متزوجة ولي أولاد حصل بيني وبين زوجي مشاكل، فهو متزوج من امرأة أخرى، ويؤدي إليها كل الحقوق وأنا لا يعرف من حقوقي شيئاً، ولا يريد أن أذهب إلى أهله منذ سنتين، فهل يجوز لي أن أقاطع أهله بسبب ابنهم، أفيدوني أفادكم الله؟","title":"ما يعدل مع زوجته ومنعها من زيارة أهله","answer":"الجواب: هذا شيء بينك وبينه إن صلحت أنت وإياه فالحمد لله، وإلا فالمحكمة تنظر بينكما، ....... خصومة، هذه مسألة خصومة، فإذا سمحت وصلحت وصبرت على ما قال لك فلا بأس وهذا إليك، فإن لم تصبري فالأمر يرجع فيه إلى المحكمة، والمحكمة تنظر في الأمر بينك وبين زوجك، أصلح الله حال الجميع.\nالمقدم: هذا بالنسبة لما لها من حقوق؟\nالشيخ: نعم.\nالمقدم: لكن هل يجوز له أن يمنعها من زيارة أهله؟\nالشيخ: عليها السمع والطاعة، عليها السمع والطاعة لزوجها فيما أمرها به بالمعروف، وقد يكون زيارتها لأهله تضره، وقد يكون منعها؛ لأنها إذا زارت أهله قالت: فيه كذا، وقالت: فيه كذا، وقالت: فيه كذا. المقصود إذا منعها من أهله تمتنع.\nالمقدم: ولا إثم عليها؟\nالشيخ: ما عليها إثم، ما هو بضروري تزور أهله، المقصود إذا منعها من أهله أو من جيرانه أو من فلان أو فلان لا تزوره تمتنع تصبر، وأما حقوقها فهذا بينها وبينه عند القاضي إلا أن تسمح. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7620/ما-يعدل-مع-زوجته-ومنعها-من-زيارة-اهله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_255/25509.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":10362,"question":"أخيراً يقول: إنه فكر في الزواج فبماذا تنصحونه؟","title":"نصيحة لمن أراد الزواج بالثانية","answer":"الجواب: الزواج مطلوب، قربة عظيمة أنا أنصحه بالمبادرة، إن كان عنده زوجة واحتاج إلى الزوجة الثانية في ...، وإن كان ما عنده زوجة فأولى وأولى أن يبادر.\nالمقدم: زوجته هذه عنده التي يشكو منها، وفكر في الزواج لعل الأمور تصلح؟\nالشيخ: لا بأس إذا أحب أن يتزوج ثانية أو ثالثة أو رابعة فالأمر واسع، لكن عليه أن يتحرى العدل، لقوله سبحانه: فَانكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلاثَ وَرُبَاعَ فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا فَوَاحِدَةً [النساء:3]، فإذا كان الرجل يغلب على ظنه أنه يعدل ويستطيع الزواج بثانية أو ثالثة أو رابعة فلا مانع، وعلى الزوجة الأولى أن تصبر، إذا عدل وأن تتقي الله وأن ترفق وأن تعاشر بالمعروف، أما إذا ظلم ولم يعدل فلها حينئذ طلب الطلاق أو الرفع إلى المحكمة، والواجب عليه أن يعدل. نعم.\nالمقدم: جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8533/نصيحة-لمن-اراد-الزواج-بالثانية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_279/27911.mp3","categories":["نصائح وتوجيهات","تعدد الزوجات"]},{"id":10540,"question":"السائلة أم عبد الله من الرياض تقول: امرأة تشتكي من زوجها حيث إنه متزوج من امرأة أخرى، وتقول: بأنه لا يعدل مع أنه شخص ملتزم ويؤدي الفروض بأوقاتها ومستقيم وتحمد الله على ذلك، ويطلب منها ألا تستخدم موانع الحمل، أما الثانية فقد ترك لها حرية الاختيار، ما هي نصيحتكم سماحة الشيخ لهم؟","title":"حكم التفريق بين الزوجتين في استخدام موانع الحمل","answer":"الجواب: نصيحتي للجميع الأول أن يعدل الزوج ويتقي الله في ذلك؛ لأن الله أوجب عليه العدل بين الزوجتين في القسم والنفقة، فلا يجر على واحدة منهن، بل يجب أن يعدل بينهما، وأما كونه يمنع هذه من الحمل من تعاطي الحبوب ولا يمنع الأخرى، هذا قد يكون له نظر في ذلك لأسباب تقتضي ذلك، وهذا محل نظر، إذا كان ما هناك أسباب تقتضي ذلك فالواجب أن يسمح لهما جميعًا؛ لأن كل واحدة تريد الولد، أما إذا كانت الممنوعة من الولد يضرها الولد مع المرض يضرها.... لها أسباب معقولة هو معذور، أما أن يمنعها من الولد بغير أسباب ويأذن للأخرى فهذا فيه نوع من الجور.\nفالواجب أن يسمح لهما جميعاً ولا يجوز لهما منع الحمل كلاهما، لا يجوز له ولا لها، بل يجب عليهما أن يجتهدا في أسباب الحمل؛ لأن الرسول ﷺ، أمر بتزوج الولود الودود وقال: إني مكاثر بكم الأمم يوم القيامة فالمطلوب تكثير النسل، يشرع للزوج والزوجة أن يجتهدا في تكثير النسل، ولعل الله ينفعهما بذلك، فإن من النعمة العظيمة أن يرزقا ذرية طيبة، فلا وجه للمنع، ولا وجه للاتفاق على المنع أيضاً إلا لعلة شرعية، لأسباب شرعية تقتضي المنع الموقت، كأن تكون مريضة يضرها الحمل كأن يكون معها رضيع يضره الحمل، أو يضرها هي أيضاً الحمل، المقصود إذا كان لأسباب شرعية فلا بأس، أما منع هذه بدون سبب شرعي، أو هذه بدون سبب شرعي، أو منعهما بدون سبب شرعي كل هذا لا يجوز، نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/8715/حكم-التفريق-بين-الزوجتين-في-استخدام-موانع-الحمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_284/28412.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":11174,"question":"هذا السائل أرسل بهذا السؤال من الزلفي (ع. م. م) يقول: سماحة الشيخ: والدي متزوج ثلاث نساء مع والدتي ولكن أبي لا يأتي والدتي علمًا بأنها هي أم الأولاد، من مدة تزيد ما يقارب على ست سنوات تقريبًا، وكان السبب في ذلك هو: أن والدي كان يأتي متأخرًا من الليل إذا كان يومها، وبعكسه مع نسائه الأخريات، ووالدتي لم تصبر على هذه الحالة وعلى هذا الظلم وغيرها، فقالت له: إذا كان هذا حضورك لي وهذه حالك معي فلا تحضر،  هل الإثم على والدي الذي ترك والدتي مدة ست سنوات أم على والدتي التي قالت: لا تحضر، عليها شيء، وهي تقصد بالحضور المتأخر من هذا الزوج، وإحضاره الطفل يجعله ينام في فراش والدتي، أرجو منكم الإجابة يا سماحة الشيخ؟","title":"العدل بين الزوجات مطلب شرعي","answer":"الجواب: لاشك أنه أخطأ لأن الواجب عليه العدل، إلا إذا كان بلغها قال: إن كانت ... وإلا طلقت هذا قد اعتذر إليها، أما كونه يقسم للثلاث ويتساهل في حق الوالدة ولا يأتي إلا في آخر الليل أو يضيعها هذا منكر ما يجوز، هذا ظلم، بل الواجب عليه إما أن يعدل وإما أن يطلق، إلا إذا رضيت قالت: أنا سامحة ولو ما جئت، إن جئت فلا بأس وإن ما جئت فلا بأس فلا بأس إذا سمحت لا بأس. سودة رضي الله عنها أم المؤمنين بنت زمعة أراد النبي ﷺ طلاقها فقالت: يا رسول الله دعني في حبالك وأنا سامحة عن حقي لعائشة فأقرها في حباله وبقيت زوجة له ولم يطلقها برضاها، فإذا سمحت والدتك فلا بأس، وإلا فلها طلب الطلاق إما أن يعدل وإما أن يطلق، والإثم عليه إذا كانت لم تسمح. نعم. المقدم: سماحة الشيخ: العدل بين الزوجات أمر مطلوب هل من كلمة توجيهية لأولئك الذين يعددون؟ الشيخ: نعم. الواجب عليهم جميعًا تقوى الله سبحانه وأن يعدلوا، فالذي عنده زوجتان أو ثلاث أو أربع الواجب عليه تقوى الله، وأن يعدل أو يخير المرغوب عنها يقول: إن شئت صبرت وإن شئت طلقت، أما أن يظلمها ويؤذيها، لا. بل يجوز له أن يقول لها: أنتِ سامحة فلا بأس وإلا طلقتكِ، فإن سمحت فالحمد لله وإلا طلقها.  أما أن يظلمها ولا يطلق لا يجوز، بل يجب العدل في المبيت وغيره؛ لأن الله جل وعلا أوجب العدل والله يقول: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19]، فالواجب العدل بين الزوجات، ويقول ﷺ: من كانت له زوجتان فمال إلى إحداهما جاء يوم القيامة وشقه مائل. فعلى الزوج أن يعدل بين الزوجتين أو أكثر، وإذا رغب عن إحداهن يقول لها: أنا راغب أنت تصبرين متى شئت جئت وإلا فلا، وإلا طلقتكِ، لا بأس قد برئ إذا سمحت لا يضره ذلك ولا حرج عليه، وإذا لم تسمح يطلقها. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/9354/العدل-بين-الزوجات-مطلب-شرعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_290/29021.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":11194,"question":"يقول: نريد من سماحتكم كلمة توجيهية للرجال الذين تزوجوا بأكثر من واحدة، وذلك بأن يراعوا حقوقهن، ويعدلوا بينهن؛ ذلك لأن بعض النساء يشتكين من الظلم، وعدم العدل، وهل من حق المرأة أن تطالب ببيت مستقل لها ولأولادها؟","title":"الحث على العدل بين الزوجات","answer":"الجواب:  الواجب على الزوج العدل، الواجب على الزوج العدل بين الزوجتين أو الثلاث أو الأربع، ويحرم عليه الظلم والجور، يقول النبي ﷺ: من كانت له امرأتان فمال إلى إحداهما جاء يوم القيامة وشقه مائل فالله جل وعلا أوجب العدل على الزوج فيما يتعلق بالقسم والنفقة. أما ما لا يستطيع كالحب، وما يتبع الحب من جماع ونحو ذلك، فهذا ليس إليه، ولا يستطيعه، ولكن عليه أن يعدل في قسمته بينهم وفي النفقة، تعطى كل واحدة كفايتها حسب الطاقة، وليس له أن يجور في ذلك.  وأما كونه يجعل لها بيتًا مستقلًا؛ هذا فيه تفصيل: إذا كانت عند أهله في محل مناسب يكفي، ولو عند أهله ما يلزم أن يكون لها بيت مستقل، يجعلها عند أبويه أو عند أمه أو عند أبيه، أو في بيته هو وإخوته، في محل مناسب ليس فيه مضرة عليها فلا بأس، ليس بشرط ذلك أن تكون مستقلة، إلا إذا كان هناك شرط عند العقد، شرط عليه أنها تكون في بيت مستقل، فالمسلمون على شروطهم، إذا كان شرط عليه عند العقد أنه يجعلها في بيت مستقل فهذا لا بأس، وإلا فإنها تسكن مع أهله ومع أبويه أو مع إخوته في محل مناسب، إذا كان البيت مناسبًا يتسع للجميع. نعم. المقدم: بارك الله فيكم، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9365/الحث-على-العدل-بين-الزوجات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_372/37210.mp3","categories":["الشروط والعيوب في النكاح","تعدد الزوجات"]},{"id":11500,"question":"سوداني مقيم في المملكة اسمه (جعفر . س) يقول: أنا رجل متزوج، ونويت الزواج من امرأة أخرى، لكن أخفيت ذلك عن زوجتي، فهي إن أخبرتها ستعارض بطبيعة الحال، فما حكم الإسلام في إخفائي لذلك الأمر عنها؟ جزاكم الله خيرًا.","title":"حكم إخفاء الرجل زواجه بالثانية عن زوجته الأولى","answer":"الجواب:  لا حرج في ذلك أن تخفي عنها؛ لكن متى تزوجت لابد من العدل، لابد من العدل بينهما إلا أن ترضى الأخيرة بعدم القسم لها فلا بأس، وإلا فلابد من العدل، تقسم لهذه ولهذه، سواء سواء، نعم. المقدم: بارك الله فيكم، جزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/9678/حكم-اخفاء-الرجل-زواجه-بالثانية-عن-زوجته-الاولى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_383/38311.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":13087,"question":"السائلة -فضيلة الشيخ- دلال من اليمن تقول في هذا  امرأة لا تنجب، ويريد الزوج أن يتزوج بأخرى لهذا السبب، وقالت هذه الزوجة: لو تزوج علي تقتل نفسها، فنريد من سماحتكم توجيه هذه المرأة، وأن تبينوا لها الحكمة من تعدد الزوجات؟","title":"حكم من تهدد بقتل نفسها إن تزوج زوجها بثانية","answer":"الجواب: لا يجوز لها قتل نفسها، هذا منكر، هذا جهل منها، وله أن يتزوج ثانية وثالثة ورابعة، الله يقول سبحانه: فَانكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلاثَ وَرُبَاعَ [النساء:3] والشارع يريد من الأمة أن تجتهد في عفة الفروج، ومكثرة النسل حتى تكثر الأمة التي تعبد الله وتطيعه، فالتي لا تنجب قد أصابها عيب كبير، والأمر إلى الله، الله حكيم عليم، عليها أن تحتسب وتصبر، وتسأل ربها العافية، وأن الله يرزقها الذرية، تسأل ربها .. تتعالج لا بأس، ولكن زوجها لا بأس أن يتزوج يطلب الذرية، وإذا قتلت نفسها؛ فإلى النار .. الله توعدها بالنار.  ولا يلزم زوجها أن يطيعها، له أن يتزوج ولو قتلت نفسها، الإثم عليها، والشر عليها، وقاتل نفسه توعده الله بالنار، نعوذ بالله. نعم. المقدم: جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11304/حكم-من-تهدد-بقتل-نفسها-ان-تزوج-زوجها-بثانية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_507/50719.mp3","categories":["قضايا المرأة","تعدد الزوجات"]},{"id":13716,"question":"في ثاني أسئلة السائل (ع. ع. ج) من الرياض يقول: هناك رجل متزوج من زوجتين، ولم يعدل بينهما لا في النفقة، ولا المبيت، فهل لسماحة الشيخ عبدالعزيز من كلمة تجاه هؤلاء الأزواج؟","title":"توجيه للأزواج بالعدل بين الزوجات","answer":"الجواب: نعم، الواجب على الزوج أن يعدل إذا كان له زوجتان أو ثلاث، فالواجب عليه أن يعدل في النفقة والقسم، ليتق الله في ذلك، وفي الخلق الحسن مهما استطاع. أما الجماع ما يجب العدل فيه؛ لأنه ليس باختياره، قد يشتهي هذه في بعض الأحيان، ولا يشتهي الأخرى، لكن في النفقة والقسم وحسن الخلق يجب أن يعدل، ويتقي الله في ذلك، لا يظلم هذه دون هذه، لا يظلمهما جميعًا، ولا يقصر في حق هذه، ويكمل في حق هذه، بل يجب أن يعدل في الجميع، ينفق على كل واحدة النفقة اللائقة بها، ويقسم لها قسم الذي فرضه الله عليه، ولكن كونه يحب هذه أكثر، أو يجامعها أكثر هذا ليس باختياره، هذا بيد الله -جل وعلا- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12087/توجيه-للازواج-بالعدل-بين-الزوجات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_545/54509.mp3","categories":["تعدد الزوجات","نصائح وتوجيهات"]},{"id":13797,"question":"بعد ذلك ننتقل إلى رسالة بعث بها السائل أخوكم عوض محمود من جمهورية مصر العربية ومقيم في السعودية جدة، يقول: أنا متزوج زوجة وقد أنجبت أربع بنات، وأريد الزواج من امرأة أخرى لكي تنجب لي أولاد ذكور، فماذا تنصحونني؟ جزاكم الله خيرًا.","title":"توجيه لمن يرغب بالزواج بالثانية لإنجاب البنين","answer":"الجواب: هذا طيب، هذا من الأسباب، والتوفيق بيد الله قد تحمل هذه ذكرًا بعد حين، وقد تتزوج امرأة تأتي بذكر وقد تأتي بإناث الأمر بيد الله، إذا تزوجت من باب الأسباب وتسأل ربك أن الله يمنحك ذرية من الذكور طيبة، لا بأس، وهذه التي أتت بأربع قد تأتي بذكور بعد ذلك، ربك على كل شيء قدير، والأمر بيده  ليس بيدها ولا بيدك، تسأل ربك أن الله يسر لك الذرية الطيبة من الذكور والإناث من هذه ومن غيرها. نعم.","link":"https://binbaz.org.sa/fatwas/12168/توجيه-لمن-يرغب-بالزواج-بالثانية-لانجاب-البنين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_536/53617.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":14130,"question":"رسالة وصلت إلى البرنامج من قطر - الدوحة باعثها مستمع من هناك يقول (م. م. ع) مقيم في الدوحة، أخونا له جمع من الأسئلة في أحد أسئلته يقول: هل يجوز للرجل أن يتزوج بامرأتين بدون علم إحداهما، مع إيهامه الثانية أنه غير متزوج؟","title":"حكم الزواج بالثانية دون علم الأولى","answer":"الجواب: هذا فيه تفصيل: يجوز أن يتزوج ثانية وثالثة بدون علم السابقات لا بأس بذلك، إذا كان مثلاً سافر إلى بلد من البلدان وتزوج فيها ويأتي إليها وقت سفره إلى هناك لا بأس بذلك. أما في البلد الواحدة فلا بد من العلم حتى يقسم بينهما وحتى يعدل بينهما، وليس له أن يوهمها أنه لا زوجة له، بل يعلم ويخبرها بأن عنده زوجة؛ لأن هذا من الخداع، فلا بد أن يعلمها أن له زوجة إذا كان في بلد واحد، يقول: نعم. ويقسم لهما جميعًا وينصفهما ويعطيهما حقهما، وليس له الخداع والمكر. أما في بلاد أخرى مثل سافر للدراسة فله أن يتزوج في البلد حتى يعف نفسه ولو ما شاور المرأة ولو ما علم المرأة، لا يضره ذلك ما دام ليس عنده العدد المسموح به وهو أربع بل عنده فرصة، فإذا كان ما عنده إلا واحدة يأخذ ثانية، ما عنده الاثنتين يأخذ ثالثة، عنده ثلاث يأخذ رابعة لا بأس لا يزيد على الأربع.\nالمقصود أنه إذا احتاج إلى ذلك وأراد أن يتزوج ليس من شرط ذلك أن يعلم زوجته إذا كانت في بلد أخرى، لكن مع مراعاة قسم الواجب والعدل في النفقة وغير هذا مما يجب على الزوج من جهة العدالة. نعم، نسأل الله للجميع الهداية. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12569/حكم-الزواج-بالثانية-دون-علم-الاولى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_615/61506.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":15373,"question":"سماحة الشيخ، هذه أختنا (م. ن. هـ) من الرياض، كتبت الحقيقة رسالة بأسلوبها الخاص، وتذكر بأنها زوجة لديها سبعة من الأولاد وبنت، زوجها تزوج عليها، تقول: لقد استشارها في ذلك، ووافقت فقط أن يعدل بينها وبين ضرتها، وتزوج، ولكنه -تقول- خان العهد الذي بيننا وهو العدل؛ لذلك فإنه لا يسأل عن أولاده، ولا يرد السلام عندما أسلم عليه، ويهددني دائمًا بالطلاق، ويميل إلى زوجته الأخرى في جميع أمورها. سماحة الشيخ تقول: هل يجب علي الصبر في ذلك، أم أشتكيه إلى الشرع أو إلى المحكمة؟مأجورين.","title":"حكم من يميل إلى زوجته الأخرى","answer":"الجواب: الواجب عليه أن يعدل، وأن يتقي الله سبحانه، هذا هو الواجب عليه، أن يعدل بينكما في القسم، وغيره، هذا الواجب عليه، فإن لم يعدل فأنت بالخيار إن شئت صبرت وسامحتيه، وإن شئت طلبت الطلاق، قولي: طلقني أو اعدل، فإذا أبى ارفعي الأمر إلى المحكمة، إما أن يعدل، وإما أن يطلق، إلا أن ترضي وتصبري، فلا بأس.  فإذا لم يعدل، ولم يطلق، فلك أن ترفعي إلى المحكمة أنت أو وليك إلى المحكمة؛ ليلزمه بالطلاق أو بالعدل، نسأل الله للجميع الهداية. المقدم: اللهم آمين، سماحة الشيخ، ميل كثير من الأزواج بعد أن يعددوا هل من كلمة توجيهية لهؤلاء؟\nالشيخ: الواجب على من كان عنده زوجتان أو ثلاث أو أربع، الواجب عليه أن يعدل في القسم وغيره، هذا هو الواجب؛ لأن الله أوجب العدل على الأزواج، وكان النبي ﷺ كان يقسم بين أزواجه ويعدل، ويقول: اللهم هذا قسمي فيما أملك، فلا تلمني فيما تملك ولا أملك كان يقسم بين نسائه ويعدل، وهو خير الناس وأفضلهم -عليه الصلاة والسلام-. فالواجب على من كان عنده زوجتان أو ثلاث أو أربع أن يعدل بينهن، وكذلك في النفقة إلا إذا كان عند إحداهن أولاد أكثر ينفق عليها بقدر حاجتها، بقدر حاجاتها وأولادها، كل واحدة بقدر حاجتها وأولادها، وعليه أن يقسم بينهن بالسوية في الليل والنهار، ويتقي الله في البشاشة وطلاقة الوجه، مع كل واحدة، لا يعبس في واحدة وينشرح للأخرى، عليه أن يتقي الله، وأن يراقب الله؛ لأن الله يقول: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ[النساء:19] هذا هو الواجب عليه، ويقول ﷺ: من كان له امرأتان فمال إلى إحداهما جاء يوم القيامة وشقه مائل. فالواجب العدل أو الطلاق، إما أن يعدل، وإما أن يطلق، إلا أن تسمح، تقول: أنا سامحه، لا بأس تجيني متى شئت فلا بأس، سودة لما أراد النبي ﷺ طلاقها قالت: «يا رسول الله، أبقني في حبالك، وأنا سامحة عن حقي لـعائشة» فأسقطت حقها وأبقاها النبي ﷺ، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13876/حكم-من-يميل-الى-زوجته-الاخرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_567/56704.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":15775,"question":"سؤاله الأخير في هذه الحلقة يقول: إنّ والده تزوج بامرأة أخرى، وحينئذٍ أساء معاملة والدته إساءة بالغة، رغم أن والدته يصفها بأنها محسنة إلى والده، فما هو توجيه سماحتكم؟جزاكم الله خيرًا.","title":"توجيه لمن يسيء تعامل الزوجة الأولى","answer":"الجواب: الواجب نصيحة الوالد، وترغيبه في العدل، وتحذيره من الجور؛ لأنه يأثم بذلك، الواجب عليه العدل بين الزوجتين، وفي الحديث الصحيح يقول النبي ﷺ: من كانت له امرأتان، فمال إلى إحداهما، جاء يوم القيامة وشقه مائل فهي عقوبة ظاهرة، نسأل الله العافية.  فالمقصود: أن الواجب العدل، كذلك الواجب أن ينصح الوالد، ويحرض على العدل، والوالدة توصى بالصبر والتحمل ومسامحة الوالد، حتى يجتمع الشمل، وحتى يهديه الله إذا رأى منها السماح، والكلام الطيب، قد يرجع إلى الصواب، ويخضع، ويقدر لها شعورها الطيب، وإذا أبى إلا عدم العدل، فلها أن تطلب الطلاق، إن أحبت الطلاق لها أن تطلب الطلاق، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14368/توجيه-لمن-يسيء-تعامل-الزوجة-الاولى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_742/nour_74205.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":15984,"question":"هذا سؤال من السائلة مسلمة من العراق، محافظة ديالي، تقول: أنا امرأة متزوجة، ولي أربعة أطفال، وقد تزوج زوجي امرأة ثانية، ولها أطفال أيضًا، والمشكلة أنه لا يعدل في معاملته بيننا، فقد انصرف عني كليًا، حتى كأنه لا وجود لي في البيت، وأطفالي يدرسون، ويحتاجون إلى مصاريف الدراسة، ولكنه لا يعطيهم، وأنا لا أستطيع أن أطلب منه، وللعلم فنحن نسكن والزوجة الثانية في نفس المسكن، وأخشى على أطفالي من الضياع من هجره للجميع، وعدم اهتمامه، فما رأيكم في هذا؟","title":"توجيه لمن لا يعدل في تعامله بين زوجتيه","answer":"الجواب: الواجب عليه تقوى الله، الواجب على الزوج أن يتقي الله، وأن يعدل، قد قال النبي ﷺ: من كان له امرأتان فمال إلى إحداهما جاء يوم القيامة وشقه مائل فالعدل واجب في النفقة بينهما والمساواة بينهما في القسمة، فإذا جار على السائلة فهذا عليه إثم في ذلك إلا إذا كان خيرها بين الطلاق وبين الصبر، فلا حرج عليه، إذا خيرها واختارت البقاء معه على ظلمه وعدم عدله فلا بأس عليه إذا خيرها، أما أنه يمنع الطلاق، ويمنع العدل، فهذا لا يجوز له. أما أولاده فعليه نفقتهم، والواجب عليه مطلقًا طلق أو لم يطلق، عليه أن يعدل في أولاده، ويحسن إليهم، ويقوم بحاجاتهم حسب طاقته، وإذا استطاعت أن تأخذ من ماله شيئًا لحاجتها فلا بأس، إذا كان لديها مال واستطاعت السائلة أن تأخذ من ماله شيئًا بغير علمه قدر حاجتها بالمعروف لأولادها ولها فلا حرج، فقد ثبت عن النبي ﷺ أنه رخص لامرأة أبي سفيان أن تأخذ من ماله بالمعروف ما يكفيها ويكفي بنيها، فإذا وجدت له مالًا تستطيع أن تأخذ منه شيئًا لها ولأولادها بغير علمه بالمعروف من غير تبذير ومن غير إسراف، فلا حرج في ذلك -إن شاء الله-، وإن لم تستطع فينبغي لها أن تتصل بأقاربه وإخوانه والذين يعزهم ويقدرهم حتى ينصحوه، حتى يشيروا عليه، لعله يهتدي، ولعله يقوم بالواجب. وينبغي لها أن تكثر من سؤال الله له الهداية حتى يوفق للعدل، وإن كان هناك حاكم شرعي في الأحوال الشخصية، يمكن أن ترفع الأمر إليه، فلا مانع من أن ترفع إليه حتى يلزمه بالعدل، ولكن مهما أمكن أن يكون ذلك من طريق المصلحين من أقاربه وجيرانه والناس الذين يعزهم فهو أولى، الإصلاح بينها وبينه من طريق الإخوان الطيبين حتى ينفق وحتى يعدل، فهذا أولى من الشكوى وأحوط وأقرب إلى السلامة، نسأل الله للجميع الهداية. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/14612/توجيه-لمن-لا-يعدل-في-تعامله-بين-زوجتيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_680/nour_68007.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":16002,"question":"هل ما يقدمه الزوج لأهل زوجته الأخرى من صدقات أو هدايا هل يؤثر ذلك في العدل بين الزوجات؟","title":"هل يشترط العدل بين أهل الزوجات؟","answer":"الجواب: لا بأس بذلك، لا حرج -إن شاء الله-، لا يؤثر، المهم العدل بينهما في أنفسهما، أما إذا أعطى أهل إحدى زوجتيه لفقرهم، أو لإحسانهم إليه، أو لأسباب أخرى، فليس هذا من باب العدل بين الزوجات، لا حرج عليه، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14622/هل-يشترط-العدل-بين-اهل-الزوجات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_747/nour_74710.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":16570,"question":"تقول: إن زوجها تزوج بأخرى، ولم يعدل بينها وبين الجديدة، ولما عاد إليها؛ امتنعت عنه، وترجو التوجيه؟","title":"حكم امتناع المرأة عن زوجها لعدم عدله معها","answer":"الجواب: الواجب عليه العدل والتوبة إلى الله من الجور، فإذا عاد إلى العدل، واستقام أمره؛ فالواجب عليك أن تمكنيه من نفسك، وأن ترجعي إلى الحق والصواب، أما إذا لم يعدل؛ فلك الحق في طلب الطلاق، والامتناع منه؛ حتى يعدل، أو يطلق، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15289/حكم-امتناع-المراة-عن-زوجها-لعدم-عدله-معها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_816/nour_81605.mp3","categories":["تعدد الزوجات","قضايا المرأة"]},{"id":16820,"question":"تقول: المشكلة الثانية في رسالتي يا سماحة الشيخ: هو التفرقة بين أولادي، هذا الزوج متزوج من امرأة ثانية، ويفضل أولاده من الأم الثانية -من الزوجة الثانية- ويحبهم كثيرًا، ويعطف عليهم، أما أنا فلي الإهمال، ولأولادي إهمال كثير، تقول: ما توجيه سماحتكم؟","title":"توجيه لمن يفضل أولاده من الزوجة الثانية على الأولى","answer":"الجواب: الواجب على الزوج أن يعدل بين الزوجتين، أو الثلاث، أو الأربع، عليه العدل، وعليه العدل في أولاده أيضًا، هذا هو الواجب على الزوج، وأن يتقي الله في ذلك، والله يقول: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] ويقول سبحانه: وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ البقرة:228] فالواجب عليه العدل، وتحري العدل، وهكذا في أولاده، يقول النبي ﷺ: اتقوا الله، واعدلوا بين أولادكم.  فليس له أن يحيف كأن يعطي أولاد إحدى الزوجتين ما لا يعطيه أولاد الأخرى، أو يخاطبهم، ويلين معهم بالكلام الطيب، والآخرون بخلاف ذلك، لا يجوز هذا، بل يجب عليه العدل في قوله، وفي أعماله، وفي ماله. وهكذا مع الزوجتين، يعدل في الزوجتين في قسمه بينهما، وفي خطابه لهما، وعدم الظلم لإحداهما، أو لإحداهن إن كن ثلاثًا فأكثر، يجب عليه العدل في كلامه، وسيرته، ومعاشرته، ونفقته إذا كن سواء، والأولاد كذلك يجب أن يعدل بينهم، وليس له أن يخص بعضهم بشيء، يقول ﷺ: اتقوا الله، واعدلوا بين أولادكم.  فإذا أعطى ولد فلانة؛ يعطي لولد الأخرى مثله، إلا إذا كانوا مرشدين، وتسامحوا؛ فلا بأس، إذا كانوا مرشدين، وسامحوه قالوا: نسامحك يا والد، وسامحوه، وهم مرشدون؛ لا بأس، وإلا فالواجب عليه العدل للذكر مثل حظ الأنثيين فإذا أعطى ولد فلانة مائة؛ يعطي الآخر مائة، إذا أعطاه ألفًا؛ يعطيه ألفًا، والأنثى نصف ذلك؛ إذا أعطى الرجل مائة يعطيها خمسينًا، وإذا أعطى الرجل ألفًا يعطيها خمسمائة، هذا الواجب، وإذا كانت الزوجتان متماثلتين في النفقة؛ أنفق عليهما سواء، فإذا كانت إحداهما عندها أولاد أكثر، كل واحدة ينفق عليها بقدر حاجتها.  المقدم: شكر الله لكم يا سماحة الشيخ، وبارك الله فيكم، وفي علمكم ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/15569/توجيه-لمن-يفضل-اولاده-من-الزوجة-الثانية-على-الاولى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_585/58517.mp3","categories":["الهبة والعطية","تعدد الزوجات"]},{"id":18460,"question":"يقول السائل محمد من جمهورية مصر العربية: رجل يريد أن يتزوج زوجة ثانية على زوجته الأولى، هل لها الحق أي: الزوجة الأولى، أن تطلب ملابس وذهبا مثل الزوجة الثانية في الزواج، أم ماذا يفعل تجاهها؟","title":"هل يلزم مساواة الزوجة الأولى بالثانية في يوم زواجها؟","answer":"الجواب: لا، لا يلزمه ذلك، يلزمه الإنفاق عليها بالمعروف، وأما ما يعطيه الزوجة الجديدة من مهر وغيره هذا يختص بالجديدة، لا يلزمه أن يعطي تلك مثلها، ولكن يقسم للجديدة يقسم لها ثلاث إذا كانت ما هي ببكر، وإن كانت بكرًا يقسم لها سبعًا، الجديدة، ثم يعدل، ثم يقسم بين الجميع. وأما أنه يعطيها مثلما أعطى الجديدة من مهر وحلي وملابس شرطتها عليه فلا، لكن يعطيها بعد.. يقسم بينهم بعد الكسوة وغيرها بعدين بعد الزواج، يسوي بينهم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17539/هل-يلزم-مساواة-الزوجة-الاولى-بالثانية-في-يوم-زواجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_785/nour_78507.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":18814,"question":"هذا السائل أبو فهد من القصيم، يقول: شخص لديه زوجة، وقد تزوج بزوجة أخرى، وطلبت الأولى أن يعطيها من الحلي مثلما يعطي الزوجة الثانية، هل يلزمه هذا الشرط؟","title":"حكم إعطاء الزوجة الأولى مثل الثانية عند الزواج بها","answer":"الجواب: إذا كان الحلي مهرًا للجديدة لا يلزم، هذا مهر، أما إذا كان بعدما تزوجها أعطاها يعطي هذه مثلها من باب العدل، يكون كسوة وحلي بينهما يتماثلان، أما إذا كان الحلي مشروط في المهر إن كان لها حلي مشروطة في المهر أو دراهم مشروط هذا لا، هذه مهر ليست داخلة في النفقة، نعم. المقدم: جزاكم الله خيرًا فضيلة الشيخ.","link":"https://binbaz.org.sa/fatwas/17954/حكم-اعطاء-الزوجة-الاولى-مثل-الثانية-عند-الزواج-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_791/nour_79123.mp3","categories":["الهبة والعطية","تعدد الزوجات"]},{"id":19202,"question":"سماحة الشيخ! إذا قامت المرأة الداعية إلى الله بالنصح المخلص على هذا المنوال الذي تفضلتم به، إذا قامت به للأخوات المتزوجات لعل له تأثير؟","title":"توجيه الداعيات إلى الله بالدعوة إلى تعدد الزوجات","answer":"الجواب: نعم، نعم، أنا أوصي الداعيات لله والمتعلمات والعالمات أوصيهن جميعًا أن يتقين الله وأن يبحثن هذا الموضوع كثيرًا، ويرشدن إلى ما أرشد الله إليه، ويوصين أخواتهن بهذا الأمر، ويشرحن لهن ما فيه من الفوائد والمصالح، وأن يكن عونًا للأزواج المؤمنين على هذا المشروع النافع المفيد للرجال والنساء جميعًا، فإن كلام الداعية المؤمنة، والمرشدة المؤمنة قد يؤثر على أخواتها في الله أكثر مما يؤثر كلام الرجل. فأنا أوصي جميع طالبات العلم، وجميع المدرسات، وجميع من لديهن علم أن يساعدن في هذا الموضوع، وأن يرشدن، فيكون لهن بذلك خير كثير، الله المستعان. نعم. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18401/توجيه-الداعيات-الى-الله-بالدعوة-الى-تعدد-الزوجات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_888/nour_88808.mp3","categories":["تعدد الزوجات"]},{"id":19203,"question":"الواقع كدت سماحة الشيخ أطلب من سماحتكم نصيحة إلى الأخوات المتزوجات، فكثير من الإخوة عندما يتزوج وهذه نيته يريد على الأقل أن يكتسب الإنفاق على أخت مسلمة لا عائل لها، زوجته تغادر المنزل وتقوم وتولول وتفسد أولاده عليه وتؤنبهم عليه أيضًا.","title":"حكم تذمر النساء من تعدد الزوجات والإنكار على الأزواج","answer":"الجواب:\n\nهذا منكر مثلما سمعت، هذا منكر وليس لها أن تفعل ذلك، ليس لأي زوجة أن تنكر على زوجها ذلك، وليس لها أن تعترض عليه، وليس لها أن تسيء إليه، ولا إلى أولاده، وإنما فعل ما أباح الله له.\n\nنعم، إذا ظلم، إذا جار عليها.. إذا لم يعدل فلها أن تتكلم، ولها أن تشكوه إلى المحكمة إلا أن تصبر وتحتسب، أما ما دام لم تر منه إلا الخير، أو حتى الآن ما بعد فعل شيئًا فإنها تصبر وتحتسب، وترجو الله أن يقدر لها الأصلح، وأن يعينها على الصبر، وسوف يجعل الله فرجًا ومخرجًا يقول الله  في كتابه العظيم: فَعَسَى أَنْ تَكْرَهُوا شَيْئًا وَيَجْعَلَ اللَّهُ فِيهِ خَيْرًا كَثِيرًا [النساء:19]، ويقول سبحانه: كُتِبَ عَلَيْكُمُ الْقِتَالُ وَهُوَ كُرْهٌ لَكُمْ وَعَسَى أَنْ تَكْرَهُوا شَيْئًا وَهُوَ خَيْرٌ لَكُمْ وَعَسَى أَنْ تُحِبُّوا شَيْئًا وَهُوَ شَرٌّ لَكُمْ وَاللَّهُ يَعْلَمُ وَأَنْتُمْ لا تَعْلَمُونَ [البقرة:216].\n\nفالله هو اللي يعلم ، فربما كان هذا الزواج سببًا لعطفه عليها ومزيد محبته لها؛ لأنه رأى من الثانية ما لم ير من الأولى، ورأى أن خصال الأولى أحسن وأن سيرتها أطيب، وأن دينها أكمل، فيعطف عليها أكثر، وربما طلق الثانية وزاد حبه للأولى، فلا ينبغي لها أن تجزع من هذا، فربما كان خيرًا لها، وإن نجح في زواجه وعدل بينهما فالحمد لله، المؤمن يحب لأخيه ما يحب لنفسه، فينبغي لها أن تحب لأخواتها في الله أن يرزقهن الله أزواجًا وذريات، هكذا المؤمن مع أخيه، يقول النبي ﷺ: لا يؤمن أحدكم حتى يحب لأخيه ما يحب لنفسه.\nوهكذا لا تؤمن المؤمنة حتى تحب لأختها ما تحب لنفسها، هذا معنى كلامه عليه الصلاة والسلام؛ لأن قوله يعم الرجال والنساء، والله المستعان. نعم.\nالمقدم: والله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18400/حكم-تذمر-النساء-من-تعدد-الزوجات-والانكار-على-الازواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_888/nour_88807.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":19204,"question":"ننتقل بعد هذا إلى قضايا أخرى ورسائل أخرى، فرسالة وصلت إلى البرنامج من المستمع ( علي. س.س.) من الجنوب، أخونا يسأل سماحة الشيخ عن الحكم فيمن يعدد الزوجات، وهل يصغي إلى الأقوال القائلة بأن ذلك يخالف الفطرة؟ وجهونا جزاكم الله خيرًا.","title":"ترك تعدد الزوجات سبب في كثرة العوانس في البيوت","answer":"الجواب: قد شرع الله  لعباده تعدد النساء إذا استطاع الزوج ذلك، ولم يخف الجور والعول في قوله جل وعلا: وَإِنْ خِفْتُمْ أَلَّا تُقْسِطُوا فِي الْيَتَامَى فَانكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلاثَ وَرُبَاعَ فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا فَوَاحِدَةً أَوْ مَا مَلَكَتْ أَيْمَانُكُمْ [النساء:3] ، وقد تزوج النبي ﷺ عدة من النساء، وتوفي ﷺ وعنده تسع، وهذا من خصائصه عليه الصلاة والسلام فيما زاد عن أربع. أما الأمة فليس لهم إلا أربع فقط، قد فرق النبي ﷺ بين من أسلم على أكثر من أربع، وأمره أن يفارق الزائد، وخيره أن يختار أربعًا ويفارق ما زاد على ذلك. فالواجب على المسلم أن يقف عند حد الله، وأن لا يزيد على ما شرع الله وهو الأربع، فإذا استطاع أن يتزوج أربعًا وقام بحقهن فلا حرج عليه في ذلك، بل ذلك أفضل له إذا استطاع ذلك لما في ذلك من المصالح من: عفة فرجه، وغض بصره، وتكثير الأمة، وتكثير النسل الذي قد ينفع الله به الأمة، وقد يعبد الله ويدعو لوالديه فيحصل لهم بذلك الخير العظيم. ولولا أنه أمر مطلوب وأمر مشروع وفيه مصالح جمة لما فعله النبي عليه الصلاة والسلام، فهو أفضل الناس وخير الناس وأحرصهم على كل خير عليه الصلاة والسلام، وقد جعل الله في تزوجه بالعدد الكثير من النساء مصالح كثيرة في تبليغ الدعوة ونشر الإسلام من طريق النساء، ومن طريق الرجال. فإذا تزوج المؤمن ثنتين أو ثلاثًا أو أربعًا لمصالح شرعية؛ لأنه يحتاج إلى ذلك، أو لقصد تكثير الأولاد أو لقصد كمال العفة وكمال غض البصر؛ لأنه قد لا تكفيه الواحدة أو الاثنتان أو الثلاث، فكل هذا أمر مطلوب شرعي، ولا يجوز لأي مسلم ولا لأي مسلمة الاعتراض على ذلك، ولا يجوز انتقاد ذلك، ولا يجوز لأي إذاعة ولا أي تلفاز أن ينشر ما يعارض ذلك، بل يجب على جميع وسائل الإعلام أن تقف عند حدها، وليس لها أن تنكر هذا الأمر المشروع، ولا يجوز لمن يقوم على وسائل الإعلام أن ينشر مقالًا لمن يعترض على ذلك، لا في الوسائل المقروءة ولا في الوسائل المسموعة، ولا في الوسائل المرئية، بل يجب على وزراء الإعلام في الدول الإسلامية أن يحذروا ذلك، وأن يتقوا الله وأن يبتعدوا عما حرم الله . وهل يرضى مسلم أن تبقى النساء عوانس في البيوت! والإنسان يستطيع يأخذ ثنتين وثلاثًا وأربعًا، هذا لا يجوز أن يفعله مسلم أو يراه مسلم يخاف الله ويرجوه. وهل يجوز لمسلمة تخاف الله وترجوه أن تنكر ذلك، وهي تعلم يقينًا أن كونها مع زوج عنده زوجة أو زوجتان أو ثلاث خير لها من بقائها بدون زوج حتى تموت عانسة لا زوج لها، وربما رزقها الله بهذا الزوج الذي ليس لها إلا جزء منه، ربما رزقها الله ذرية صالحة تنفعها في الدنيا والآخرة، وربما حصل لها بذلك عفة فرجها وغض بصرها وحسن سمعتها وسلامة عرضها. فالواجب على الدول الإسلامية عامة وعلى حكومتنا خاصة إظهار هذا الأمر وتأييد هذا الأمر، والإنكار على من عارض هذا الأمر في أي وسيلة مرئية أو مسموعة أو مقروءة، بل يجب إنكار ذلك. وإنه ليسوءني كثيرًا ويسوء كل مسلم يخاف الله أن يسمع في إذاعة أو يشاهد في تلفاز أو يقرأ في صحيفة من يعترض على شرع الله، ويدعو إلى الاقتصار على الواحدة، إلا على الوجه الشرعي إذا خاف ألا يقوم بالواجب، أو عجز عن أن يقوم باثنتين، فهذا قد وضحه الله  لكن من استطاع أن يتزوج ثنتين أو ثلاثًا أو أربعًا فلا حرج عليه، بل هو مأجور ومشكور إذا نوى بذلك إظهار دين الله وتكثير الأمة وغض بصره وإحصان فرجه، والإحسان إلى أخواته في الله المحتاجات إلى النكاح، فهو مشكور ومأجور. والواجب على جميع المسلمين وعلى جميع المسلمات أن يرضوا بما شرع الله، وأن يحذروا الاعتراض على ما شرعه الله، وأن يخافوا نقمته سبحانه وعقابه في اعتراضهم ومخالفتهم لأمر الله ، وقد قال الله  في كتابه العظيم: ذَلِكَ بِأَنَّهُمْ كَرِهُوا مَا أَنزَلَ اللَّهُ فَأَحْبَطَ أَعْمَالَهُمْ [محمد:9] ، فأخشى على من كره هذا المشروع أن يحبط عمله وأن يخرج من دينه وهو لا يشعر، نسأل الله العافية. وقال تعالى: ذَلِكَ بِأَنَّهُمُ اتَّبَعُوا مَا أَسْخَطَ اللَّهَ وَكَرِهُوا رِضْوَانَهُ فَأَحْبَطَ أَعْمَالَهُمْ [محمد:28].\nفالمقصود أنه يجب على المؤمن أن يرضى بما شرعه الله، وأن يبغض ما أبغضه الله، وأن يكره ما كرهه الله، وأن يحب ما أحبه الله في جميع الأمور، إذا كان مسلمًا مؤمنًا يخاف الله ويرجوه، نسأل الله للجميع الهداية والسلامة. المقدم: اللهم آمين، جزاكم الله خيرًا الواقع سماحة الشيخ وأنتم تتفضلون بهذا التوجيه المخلص كثيرًا ما نسمع عن كثرة العوانس في البيوت، لعل لكم من كلمة سماحة الشيخ؟ الشيخ: هذا ثابت عندنا، ولهذا نوصي جميع النساء أن لا يمتنعن من الزوج الذي عنده زوجة، نوصيهن جميعًا أن يحرصن على عفتهن وسمعتهن الحسنة، وعلى حفظ فروجهن وغض أبصارهن، وعلى حفظ أعراضهن أن يبادرن بالزواج ولو كن جارات، ولو كانت ثانية أو ثالثة أو رابعة، فأنا أوصي بهذا، وأسأل الله أن يهدينا جميعًا لما يرضيه، وأوصي الأزواج القادرين أن يتزوجوا وأن يعفوا كثيرًا من نساء أمتهم، وأن يحرصوا على تكثير النسل، وعلى حفظ فروجهم وغض أبصارهم بما أحل الله لا ما حرم الله. كثير من الناس -نعوذ بالله- يأبى أن يتزوج ثانية، ولكنه يرضى بالصديقات فيما حرم الله، وتعلم زوجته ذلك، وذلك قد يكون أحب إليها من زوجة مسلمة على الوجه الشرعي، فهي تعلم عنه أنه يذهب إلى المحرمات وإلى الصديقات وإلى الزنا، ولكن لا يهمها ذلك، لكن لو تزوج لغضبت وأنكرت ولا حول ولا قوة إلا بالله، فترضى بالحرام أو تقر الحرام ولكن لا ترضى بالحلال، هذه من المصائب، ومن ضعف الدين ومن ضعف الإيمان وقلة البصيرة، نسأل الله الهداية والسلامة. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18399/ترك-تعدد-الزوجات-سبب-في-كثرة-العوانس-في-البيوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_888/nour_88806.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":19703,"question":"الواجب في العدل بين النساء هل هو في المبيت والنفقة فقط؟","title":"فيم يكون العدل بين النساء","answer":"الجواب: في القسم والنفقة، كلٌّ على قدره، يقول ﷺ: اللهم هذا قسمي فيما أملك، فلا تلمني فيما تملك ولا أملك، يقسم بينهم، والنفقة على حسب أحوالهن، فمَن كانت عندها عيال فإنَّ نفقتها أكثر، كلٌّ على قدره.","link":"https://binbaz.org.sa/fatwas/21693/فيم-يكون-العدل-بين-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/%D9%81%D9%8A%D9%85%20%D9%8A%D9%83%D9%88%D9%86%20%D8%A7%D9%84%D8%B9%D8%AF%D9%84%20%D8%A8%D9%8A%D9%86%20%D8%A7%D9%84%D9%86%D8%B3%D8%A7%D8%A1.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]}]
